INSERT INTO "provinces" ("id", "slug", "name_en", "name_kh", "region", "description_en", "description_kh", "emoji", "cover_color", "cover_image", "latitude", "longitude", "is_featured", "sort_order") VALUES
(1,'phnom-penh','Phnom Penh','រាជធានីភ្នំពេញ','Central','The vibrant capital city of Cambodia — a living mix of history, modernity, royal architecture, and incredible street food along the Mekong riverfront.','រាជធានី​ភ្នំពេញ​ជា​ទីក្រុង​ដ៏​រស់​រវើក​របស់​កម្ពុជា','🏙️','#C0392B','images/province/pp.jpg',11.5564000,104.9282000,1,1),
(2,'siem-reap','Siem Reap','សៀមរាប','Northwest','Home of the legendary Angkor Wat temple complex — one of the greatest archaeological wonders of the world, set among lush jungle and ancient ruins.','ទីក្រុង​សៀមរាប​ជា​ទី​លំនៅ​របស់​ប្រាសាទ​អង្គរវត្ត','🏛️','#8B4513','images/province/sr.jpg',13.3671000,103.8448000,1,2),
(3,'battambang','Battambang','បាត់ដំបង','Northwest','Cambodia''s second-largest city — famous for the bamboo train, Phare Circus, French colonial architecture, and golden rice fields stretching to the horizon.','ទីក្រុង​ធំ​ទី​ពីរ​របស់​កម្ពុជា — ល្បី​ល្បាញ​ដោយ​រថ​ភ្លើង​ក្រួស','🚂','#7A5C00','images/province/btb.jpg',13.0957000,103.2022000,1,3),
(4,'sihanoukville','Preah Sihanouk','ព្រះសីហនុ','Coast','Cambodia''s premier beach destination with stunning white-sand beaches, crystal-clear waters, and nearby paradise islands perfect for snorkeling and diving.','គោលដៅ​ដ៏​ល្អ​ជាង​គេ​នៅ​ Cambodia​ ជាមួយ​ដីខ្សាច់​ស','🏖️','#1A7A8A','images/province/phn.png',10.6097000,103.5297000,1,4),
(5,'kampot','Kampot','កំពត','Coast','A sleepy riverside town famous for the world''s finest pepper, French villas, cave temples, and the iconic Bokor Hill Station above the clouds.','ទីក្រុង​ស្ងប់ស្ងាត់​ជាប់​ទន្លេ ល្បី​ដោយ​ម្រេច','🌶️','#2D6A4F','images/province/kp.jpg',10.6167000,104.1833000,1,5),
(6,'kep','Kep','កែប','Coast','A tiny coastal gem famous for its sweet crab market, pepper farms, national park, and the crumbling villas of Cambodia''s former French Riviera.','ទីក្រុង​តូច​ជាប់​សមុទ្រ​ល្បី​ដោយ​ក្តាម​ស្ងោរ','🦀','#1B6B4A','images/province/kep.jpg',10.4833000,104.2833000,0,6),
(7,'kratie','Kratie','ក្រចេះ','East','A charming riverside town on the Mekong — famous for rare Irrawaddy dolphins, French colonial streets, and the sacred Sambok Mountain.','ទីក្រុង​ចម្រើន​ជាប់​ទន្លេ​មេគង្គ ល្បី​ដោយ​ត្រី​ដូរ','🐬','#1A4A6B','images/province/kj.jpg',12.4881000,106.0188000,0,7),
(8,'mondulkiri','Mondulkiri','មណ្ឌលគិរី','East','The wild east of Cambodia — misty highlands, elephant sanctuaries, roaring waterfalls, and Bunong indigenous culture hidden in ancient forests.','ខេត្ត​ ភាគ​ខាង​កើត​ដ៏​ព្រៃ​វ៉ារ','🐘','#1B5E20',NULL,12.4578000,107.1878000,1,8),
(9,'ratanakiri','Ratanakiri','រតនគិរី','Northeast','Remote northeastern highlands with volcanic crater lakes, tribal villages, waterfalls, and some of Cambodia''s last pristine jungle.','ខេត្ត​ភ្នំ​ខាង​ជើង​ខាង​កើត​ ជាមួយ​បឹង​ភ្នំ​ភ្លើង','🌋','#2D5A1B',NULL,13.7394000,107.0050000,0,9),
(10,'takeo','Takeo','តាកែវ','Central','Ancient heartland of the Khmer civilization — home to Angkor Borei, the cradle of Khmer culture, and the stunning Phnom Da hilltop temple.','មណ្ឌល​បុរាណ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🏊','#5D4037','images/province/tk.jpg',10.9908000,104.7850000,0,10),
(11,'kandal','Kandal','កណ្តាល','Central','Surrounding Phnom Penh, Kandal is rich with silk weaving villages, silver smithing communities, and the ancient Udong royal capital ruins.','ជុំ​វិញ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🌾','#795548','images/province/kd.jpg',11.2167000,105.0000000,0,11),
(12,'kampong-cham','Kampong Cham','កំពង់ចាម','Central','A historic Mekong city with French colonial charm, sacred rubber plantations, the famous Bamboo Bridge, and twin hilltop temples.','ទីក្រុង​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🕌','#6D4C41','images/province/kpc.jpg',11.9939000,105.4640000,0,12),
(13,'kampong-thom','Kampong Thom','កំពង់ធំ','Central','Gateway to the pre-Angkorian Sambor Prei Kuk temple complex — a UNESCO site older than Angkor Wat, set in deep jungle.','ច្រករបៀង​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🗿','#5D4037','images/province/kpt.jpg',12.7111000,104.8897000,0,13),
(14,'kampong-speu','Kampong Speu','កំពង់ស្ពឺ','Central','Home to the Cardamom Mountains — Cambodia''s largest protected wilderness with trekking, waterfalls, and rare wildlife.','ខេត្ត​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🏔️','#546E7A',NULL,11.4531000,104.5211000,0,14),
(15,'kampong-chhnang','Kampong Chhnang','កំពង់ឆ្នាំង','Central','Famous for traditional Khmer pottery — a floating village destination on the Tonle Sap with unique stilted homes and fish farms.','ល្បី​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🏺','#795548',NULL,12.2500000,104.6667000,0,15),
(16,'pursat','Pursat','ពោធិ៍សាត់','Northwest','Gateway to the Cardamom Mountains and the pristine Tonle Sap lake — known for orange groves, marble carving, and ecotourism.','ច្រករបៀង​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​ ​','🌊','#1A5276','images/province/ps.jpg',12.5386000,103.9194000,0,16),
(17,'oddar-meanchey','Oddar Meanchey','ឧត្តរមានជ័យ
