INSERT INTO "places" ("id", "province_id", "category_id", "name_en", "name_kh", "description_en", "description_kh", "highlights_en", "highlights_kh", "things_to_do_en", "things_avoid_en", "best_time_en", "best_time_kh", "getting_there_en", "icon", "image_url", "images", "latitude", "longitude", "opening_hours", "entry_fee", "duration", "main_product_en", "main_product_kh", "services_en", "difficulty", "is_featured", "is_active", "sort_order", "created_at", "zone", "entry_fee_usd", "estimated_food_usd", "avg_visit_hrs", "kids_friendly", "picnic_friendly", "on_site_food", "planner_tags") VALUES
(1,1,1,'Royal Palace','ព្រះបរមរាជវាំង','The Royal Palace of Cambodia is a stunning royal residence of the King showcasing golden spires the sacred Silver Pagoda with its Emerald Buddha and exquisite Khmer architecture.','ព្រះបរមរាជវាំងកម្ពុជា គឺជាព្រះរាជដំណាក់ដ៏ស្រស់ស្អាតរបស់ព្រះមហាក្សត្រ ដែលបង្ហាញពីប៉មមាសភ្លឺចែងចាំង វត្តព្រះកែវមរកតដ៏សក្ការៈបូជា និងស្ថាបត្យកម្មខ្មែរដ៏វិចិត្រសិល្បៈ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'👑','images/pp_royal_palace.webp','images/pp_royal_palace.webp|images/pp_silver_pagoda.jpg',11.5638000,104.9306000,'Daily 8am–11am, 2pm–5pm','$10','2',NULL,NULL,NULL,NULL,1,1,1,'2026-03-19 13:14:35','near',1.00,5.00,2.0,1,0,0,'culture'),
(2,1,1,'Tuol Sleng Genocide Museum','សារមន្ទីរប្រល័យពូជសាសន៍ទួលស្លែង','Tuol Sleng Genocide Museum is the haunting former S21 prison turned museuma powerful memorial to the victims of the Khmer Rouge regime that must be visited to truly understand Cambodia''s history.','សារមន្ទីរប្រល័យពូជសាសន៍ទួលស្លែង គឺជាគុក S-21 ចាស់ដែលត្រូវបានបម្លែងជាសារមន្ទីរ ដែលជាទីរំលឹកដ៏មានអត្ថន័យជ្រាលជ្រៅចំពោះជនរងគ្រោះក្រោមរបបខ្មែរក្រហម ដែលគួរត្រូវបានទៅទស្សនា ដើម្បីយល់ដឹងយ៉ាងពិតប្រាកដអំពីប្រវត្តិសាស្ត្ររបស់កម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕯️','images/pp_tuol_sleng.jpg','images/pp_tuol_sleng.jpg',11.5493000,104.9178000,'Daily 8am–5pm','$5','2',NULL,NULL,NULL,NULL,1,1,2,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,0,0,'culture'),
(3,1,7,'Phnom Penh Night Market','ផ្សាររាត្រីភ្នំពេញ','Phnom Penh Night Market offers one of the best street food experiences in Cambodia with hundreds of stalls serving grilled meats fresh noodles tropical fruits and traditional Khmer desserts along the riverside.','ផ្សាររាត្រីភ្នំពេញ ផ្តល់នូវបទពិសោធន៍អាហារតាមផ្លូវដ៏ល្អបំផុតមួយនៅកម្ពុជា ដោយមានស្តង់ជាច្រើនមានលក់សាច់អាំង មីស្រស់ ផ្លែឈើ និងបង្អែមខ្មែរប្រពៃណី នៅតាមបណ្តោយមាត់ទន្លេ។','','','','','','','','🌙','images/pp_night_market.jpg','images/pp_night_market.jpg',11.5670000,104.9280000,'Daily 5pm–midnight','Free','3','','','','Easy',0,1,3,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,0,1,'food'),
(4,1,1,'National Museum of Cambodia','សារមន្ទីរជាតិ','The National Museum of Cambodia is the country’s most important museum housing one of the world’s finest collections of Khmer sculpture and art set in a stunning traditional redbrick building.','សារមន្ទីរជាតិកម្ពុជា គឺជាសារមន្ទីរសំខាន់បំផុតរបស់ប្រទេស ដែលរក្សាទុកសំណុំសិល្បៈ និងចម្លាក់ខ្មែរដ៏ល្អឥតខ្ចោះមួយក្នុងពិភពលោក ដែលស្ថិតនៅក្នុងអគារឥដ្ឋក្រហមបែបប្រពៃណីដ៏ស្រស់ស្អាត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏺','images/pp_national_museum.jpg','images/pp_national_museum.jpg',11.5667000,104.9294000,'Daily 8am–5pm','$5','2',NULL,NULL,NULL,NULL,0,1,4,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,0,0,'culture'),
(5,1,3,'Sisowath Quay','មាត់ទន្លេ ស៊ីសុវត្ត','Sisowath Quay is a beautiful promenade along the confluence of the Tonle Sap and Mekong rivers perfect for sunset walks riverside dining and watching monks collect alms at dawn.','មាត់ទន្លេស៊ីសុវត្ថិ គឺជាផ្លូវដើរលំហែដ៏ស្រស់ស្អាតតាមបណ្តោយចំណុចប្រសព្វរវាងទន្លេសាប និងទន្លេមេគង្គ ដែលល្អបំផុតសម្រាប់ដើរលំហែពេលថ្ងៃលិច បរិភោគអាហារនៅមាត់ទន្លេ និងមើលព្រះសង្ឃបិណ្ឌបាតនៅពេលព្រឹក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/pp_sisowath_quay.png','images/pp_sisowath_quay.png|images/pp_riverside_promenade.jpg',11.5700000,104.9300000,'Always open','Free','1',NULL,NULL,NULL,NULL,1,1,5,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,1,1,'relax'),
(6,2,1,'Angkor Wat','អង្គរវត្ត','The largest religious monument in the world and symbol of Cambodia  a breathtaking 12thcentury temple complex surrounded by moats jungle and ancient galleries filled with intricate basreliefs.','អង្គរវត្ត ជាវិមានសាសនាធំបំផុតលើពិភពលោក និងសញ្ញារបស់កម្ពុជា គម្របដោយទឹកជ្រោះ ព្រៃ និងសិល្បៈបុរាណ ពោរពេញដោយចម្លាក់លំអរយ៉ាងស្មុគស្មាញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏛️','images/sr_angkor_wat.webp','images/sr_angkor_wat.webp|images/sr_angkor_thom_bayon.jpg',13.4125000,103.8669000,'Daily 5am–6pm','$37/day','4',NULL,NULL,NULL,NULL,1,1,1,'2026-03-19 13:14:35','near',37.00,5.00,2.0,1,0,0,'culture'),
(7,2,1,'Angkor Thom & Bayon','អង្គរធំ','The ancient walled city with the iconic Bayon temple  famous for its 216 giant stone faces smiling serenely in all directions and the famous Elephant Terrace.','អង្គរធំ ជាទីក្រុងបុរាណមានជួរទ្វារបិទជុំវិញ និងវត្តបាយ័នដ៏ល្បីល្បាញ ពេញនិយមសម្រាប់មុខថ្មធំ ២១៦ បង្ហាញញញឹមស្រស់ស្រាយទាំង៤ទិស និងឆ្នេរសោះដ៏ល្បីល្បាញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'😊','images/sr_angkor_thom_bayon.jpg','images/sr_angkor_thom_bayon.jpg|images/sr_angkor_wat.webp',13.4412000,103.8589000,'Daily 5am–6pm','Included in Angkor Pass','3',NULL,NULL,NULL,NULL,1,1,2,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,0,0,'culture'),
(8,2,1,'Ta Prohm Temple','ប្រាសាទតាព្រហ្ម','The mysterious jungle temple where giant strangler fig and silkcotton trees have wrapped their roots around ancient stone  famously used in the Tomb Raider film.','ប្រាសាទតាព្រហ្ម វត្តព្រៃមានអាថ៌កំបាំងដែលដើមផ្លែឈើធំ និងដើមសូត្រត្បូងព្រៃរុំឫសជុំវិញថ្មបុរាណ ត្រូវបានប្រើល្បីល្បាញក្នុងភាពយន្ត Tomb Raider។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌳','images/sr_ta_prohm.webp','images/sr_ta_prohm.webp',13.4347000,103.8892000,'Daily 7:30am–5:30pm','Included in Angkor Pass','2',NULL,NULL,NULL,NULL,1,1,3,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,0,0,'culture'),
(9,2,5,'Pub Street & Night Market','ផ្លូវដើរ និងផ្សាររាត្រី','The buzzing heart of Siem Reap nightlife  lined with bars restaurants souvenir stalls cultural performances and the famous Angkor Night Market.','ផ្លូវដើរ និងផ្សាររាត្រី ជាបេះដូងកម្សាន្តពេលយប់នៅសៀមរាប មានបារ ភោជនីយដ្ឋាន ស្តង់អនុស្សាវរីយ៍ ការបង្ហាញវប្បធម៌ និងផ្សាររាត្រីអង្គរដ៏ល្បីល្បាញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎉','images/sr_pub_street.jpg','images/sr_pub_street.jpg',13.3622000,103.8592000,'Daily 5pm–late','Free','2',NULL,NULL,NULL,NULL,1,1,4,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,0,0,'fun'),
(10,2,2,'Tonle Sap Lake','បឹងទន្លេសាប','The largest freshwater lake in Southeast Asia  home to extraordinary floating villages unique birds fish and a fascinating waterbased way of life.','បឹងទន្លេសាប គឺជាបឹងទឹកសុទ្ធធំជាងគេនៅអាស៊ីអាគ្នេយ៍ មានភូមិអណ្តែតលើទឹកដ៏អស្ចារ្យ បក្សី និងត្រីពិសេស និងជីវិតលើទឹកដ៏ទាក់ទាញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐟','images/sr_tonle_sap.webp','images/sr_tonle_sap.webp',13.0000000,104.0000000,'Boat tours daily','$10–20','3',NULL,NULL,NULL,NULL,1,1,5,'2026-03-19 13:14:35','near',1.00,5.00,2.0,1,1,0,'nature'),
(11,3,5,'Bamboo Train (Lorry)','ជិះឡូរី','A lively bamboo rail experience through Battambang countryside. Travelers ride a small open lorry, see rice fields and village life, and enjoy a playful local transport tradition.','ជិះឡូរី បទពិសោធន៍ល្បីបំផុតនៅបាត់ដំបង ជិះលើឡូរីឈើ តាមបន្ទាត់រថភ្លើងចាស់ឆ្លងកាត់វាលស្រូវ និងភូមិ ដោយល្បឿនអស្ចារ្យ។','Traditional bamboo rail cart ride · Countryside and rice-field views · Local souvenir stalls · Easy fun activity near Banan district','ជិះរទេះឫស្សីប្រពៃណី|ទេសភាពជនបទ និងវាលស្រែ|តូបលក់វត្ថុអនុស្សាវរីយ៍ក្នុងស្រុក|សកម្មភាពកម្សាន្តងាយស្រួលក្បែរស្រុកបាណន់','Ride the bamboo lorry · Take photos along the track · Try local snacks · Buy small souvenirs from local sellers','Do not stand while the lorry is moving · Avoid loose hats or bags on the track · Confirm the price before riding','Morning or late afternoon for cooler weather and softer light.','','About 20-25 km from Battambang city by tuk-tuk, car, or motorbike.','🚂','images/btb_bamboo_train.webp','images/btb_bamboo_train.webp|images/btb/Bamboo Train (Lorry)/1.jpg|images/btb/Bamboo Train (Lorry)/2.jpg|images/btb/Bamboo Train (Lorry)/3.jpg|images/btb/Bamboo Train (Lorry)/4.jpg|images/btb/Bamboo Train (Lorry)/5.jpg|images/btb/Bamboo Train (Lorry)/6.jpg|images/btb/Bamboo Train (Lorry)/7.jpg|images/btb/Bamboo Train (Lorry)/8.jpg|images/btb/Bamboo Train (Lorry)/9.jpg|images/btb/Bamboo Train (Lorry)/10.jpg',13.0200000,103.1800000,'Daily 7am–5:30pm','$5','2','Feature: traditional lorry/bamboo train ride; category: fun and local transport heritage; distance: about 24 km from the city.','ជិះឡូរីឈើ','Food &amp; Drink, Souvenir Shops, Bike Rental, Photo Spots','Easy',1,1,1,'2026-03-19 13:14:35','near',5.00,5.00,1.5,1,0,1,'fun,culture,local'),
(12,3,1,'Wat Banan Temple','ប្រាសាទបាណន់','An ancient hilltop temple in Banan district with five sandstone towers, mountain scenery, caves, water ponds and a peaceful rural setting.','ប្រាសាទបាណន់ ជាប្រាសាទបុរាណលើកំពូលភ្នំ មានប្រាង្គថ្មប្រាំ ទេសភាពព្រៃភ្នំ ល្អាងធម្មជាតិ គូទឹក និងបរិយាកាសជនបទស្ងប់ស្ងាត់។','Ancient temple; worship site; mountain forest views; natural caves; local fruit stalls','ប្រាសាទបុរាណ; ទីសក្ការៈបូជា; ទេសភាពព្រៃភ្នំ; ល្អាងភ្នំធម្មជាតិ; កន្លែងលក់ផ្លែឈើក្នុងស្រុក','Climb to the temple; explore the caves; enjoy mountain views; try local fruit; hire a local guide','Dress modestly and avoid climbing fragile temple stones','Morning or late afternoon','ពេលព្រឹក ឬល្ងាច','About 24 km from Battambang city in Banan district. Tuk-tuk, car or motorbike are suitable.','🏛️','images/btb_banan.jpg','images/btb_banan.jpg|images/btb/Wat Banan Temple/1.png|images/btb/Wat Banan Temple/2.jpg|images/btb/Wat Banan Temple/3.png|images/btb/Wat Banan Temple/4.jpg|images/btb/Wat Banan Temple/5.jpg|images/btb/Wat Banan Temple/6.jpg|images/btb/Wat Banan Temple/7.jpg|images/btb/Wat Banan Temple/8.jpg|images/btb/Wat Banan Temple/9.jpg|images/btb/Wat Banan Temple/10.jpg',12.8497000,103.0756000,'Daily','Check locally','2-3 hours','Ancient temple, mountain views and caves','ប្រាសាទបុរាណ ទេសភាពភ្នំ និងល្អាង','Food &amp; drink / ម្ហូបអាហារ និងភេសជ្ជៈ; local fruit / ផ្លែឈើក្នុងស្រុក; guide / អ្នកណែនាំ; boat and rest huts / ទូក និងតូបសម្រាក','Moderate',1,1,120,'2026-03-19 13:14:35','mid',NULL,6.00,2.5,1,1,1,'culture,temple,history,mountain,nature'),
(13,3,5,'Phare Cambodian Circus','សណ្ឋាគារ Phare','Worldrenowned circus by young Cambodian artists blending acrobatics music and storytelling. One of the most unforgettable performances in Southeast Asia.','ចក្ររង្វិល Phare ការសម្តែងសៀកល្បីទូទាំងសកល ដោយជនជាតិខ្មែរ បញ្ចូលអាក្រូបាទ តន្ត្រី និងរឿងនិទាន។ ជាការសម្តែងមិនអាចភ្លេចបាននៅអាស៊ីអាគ្នេយ៍។',NULL,'សៀកសម័យថ្មីបែបខ្មែរ|ការសម្តែងសិល្បៈ និងតន្ត្រី|រឿងរ៉ាវវប្បធម៌បាត់ដំបង|សមរម្យសម្រាប់គ្រួសារ|បទពិសោធន៍ពេលល្ងាច',NULL,NULL,NULL,NULL,NULL,'🎪','images/btb_circus.jpg','images/btb_circus.jpg',13.0957000,103.2022000,'Fri–Sat 8pm','$15–30','2','Circus Performance — Acrobatics & Storytelling','សម្តែងអាក្រូបាត និងរឿងនិទាន','Restaurant, Bar, Gift Shop, Ticket Booking',NULL,1,1,3,'2026-03-19 13:14:35','near',1.00,8.00,2.0,1,0,1,'fun,culture,art,food'),
(14,3,4,'Phnom Sampeau & Bat Caves','ភ្នំសំពៅ','A major Battambang mountain site with caves, pagodas, Khmer Rouge history, viewpoints and the famous evening bat flight.','ភ្នំសំពៅ ជាតំបន់ទេសចរណ៍សំខាន់ មានទេសភាពភ្នំ ល្អាងធម្មជាតិ ល្អាងប្រចៀវ ចម្លាក់ពុទ្ធប្បវត្តិ ប្រវត្តិសាស្រ្តខ្មែរក្រហម និងទស្សនីយភាពប្រចៀវហោះពេលល្ងាច។','Mountain views; natural caves; bat cave; Buddhist carvings; Khmer Rouge history; night market street','ទេសភាពភ្នំ; ល្អាងធម្មជាតិ; ល្អាងប្រចៀវ; ចម្លាក់ពុទ្ធប្បវត្តិ; ប្រវត្តិសាស្រ្តខ្មែរក្រហម; ផ្សាររាត្រីវិថីទេសចរណ៍','Climb or ride up the mountain; visit caves and pagodas; watch bats around sunset','Be careful near cave edges and dress modestly at pagodas','Late afternoon for sunset and bats','ពេលល្ងាចសម្រាប់ថ្ងៃលិច និងមើលប្រចៀវ','In Phnom Sampeau commune, Banan district; transport is available from Battambang city.','⛰️','images/btb_sampeau.webp','images/btb_sampeau.webp',12.9533000,102.9650000,'Daily','Check locally','3-4 hours','Bat cave, mountain views and history','ល្អាងប្រចៀវ ទេសភាពភ្នំ និងប្រវត្តិសាស្រ្ត','Food & drink / ម្ហូបអាហារ និងភេសជ្ជៈ; transport up mountain / សេវាដឹកភ្ញៀវឡើងភ្នំ; local market / ផ្សារ','Moderate',1,1,124,'2026-03-19 13:14:35','mid',NULL,6.00,3.0,1,1,1,'mountain,nature,culture,history,fun'),
(15,4,6,'Otres Beach','ឆ្នេរអូត្រែ','The most beautiful and relaxed beach near Sihanoukville  a long stretch of white sand fringed by palm trees with calm waters perfect for swimming and sunsets.','ឆ្នេរអូត្រែ ឆ្នេរដ៏ស្រស់ស្អាត និងស្ងប់ស្ងាត់ជិតព្រះសីហនុ ដីស ដើមត្នោត និងទឹកស្ងប់ស្ងាត់សម្រាប់ហែលលេង និងថ្ងៃលិច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏖️','images/Otres Beach.jpg','images/Otres Beach.jpg',10.5600000,103.5200000,'Always open','Free',NULL,NULL,NULL,NULL,NULL,1,1,1,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,0,0,'beach'),
(16,4,6,'Koh Rong Island','កោះរ៉ុង','A tropical paradise island with bioluminescent plankton beaches jungle interior pristine dive sites and the vibrant Long Beach village.','កោះរ៉ុង កោះស្ថិតក្នុងស្រុកព្រៃស្ទឹកស្លាប ផ្ទៃទឹកភ្លឺពណ៌ខៀវ កន្លែងលេងទឹក និងភូមិ Long Beach សម្បូរបែប។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏝️','images/Koh Rong Island.jpg','images/Koh Rong Island.jpg',10.6500000,103.3167000,'Ferries daily','$25 return ferry',NULL,NULL,NULL,NULL,NULL,1,1,2,'2026-03-19 13:14:35','near',2.00,5.00,2.0,1,0,0,'beach'),
(17,4,6,'Koh Rong Samloem','កោះរ៉ុងសន្លឹម','The quieter and more pristine sister island  famous for its stunning Saracen Bay crystal clear snorkeling waters and complete escape from the modern world.','កោះរ៉ុងសន្លឹម កោះបងប្អូនស្ងប់ស្ងាត់ និងស្អាត ល្បីល្បាញសម្រាប់ Saracen Bay ដ៏អស្ចារ្យ ទឹកស្អាតសម្រាប់ snorkelling និងភាពស្ងប់ស្ងាត់ពីពិភពទំនើប។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🤿','images/Koh Rong Samloem.jpg','images/Koh Rong Samloem.jpg',10.5667000,103.3833000,'Ferries daily','$25 return ferry',NULL,NULL,NULL,NULL,NULL,1,1,3,'2026-03-19 13:14:35','near',2.00,5.00,2.0,1,0,0,'beach'),
(18,5,4,'Bokor Hill Station','ស្ថានីយភ្នំបូករ','A haunting Frenchera hill station perched above the clouds at 1079m  featuring an abandoned casino art deco buildings waterfalls and stunning coastal views.','ស្ថានីយភ្នំបូករ ស្ថានីយភ្នំសម័យបារាំងនៅកំពូលពពក ១,០៧៩មែត្រ មានកាស៊ីណូ abandono អគារតិចឌេកូ ទឹកជ្រោះ និងទិដ្ឋភាពឆ្នេរអស្ចារ្យ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'☁️','images/Bokor Hill Station.jpg','images/Bokor Hill Station.jpg',10.5167000,104.0333000,'Daily 6am–6pm','$5 park fee','4',NULL,NULL,NULL,'Moderate',1,1,1,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,1,0,'mountain'),
(19,5,2,'Phnom Chhngok Cave Temple','ប្រាសាទរូងភ្នំជ្ងុក','An extraordinary cave temple inside a mountain  ancient Khmer carvings and a sacred linga shrine hidden inside a dramatic limestone cavern.','ប្រាសាទរូងភ្នំជ្ងុក វត្តក្នុងរូងភ្នំអស្ចារ្យ មានចម្លាក់ខ្មែរបុរាណ និងបារមីលីងក្រសោបនៅក្នុងរូងថ្មថ្លា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕍','images/Phnom Chhngok Cave Temple.jpg','images/Phnom Chhngok Cave Temple.jpg',10.6667000,104.2000000,'Daily 7am–5pm','$1','2',NULL,NULL,NULL,NULL,1,1,2,'2026-03-19 13:14:35','near',1.00,5.00,2.0,1,1,0,'nature'),
(20,5,3,'Kampot Riverside','មាត់ទន្លេកំពត','The most charming riverside in Cambodia  lined with beautifully restored French colonial buildings boutique cafés pepper restaurants and a bridge famous for its sunsets.','មាត់ទន្លេកំពត មាត់ទន្លេមានភាពស្រស់ស្អាតបំផុតនៅកម្ពុជា មានអគារសម័យបារាំងបានទ្រទ្រង់ ហាងកាហ្វេបុទិក ភោជនីយដ្ឋានម្រេច និងស្ពានល្បីដោយមានថ្ងៃលិច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/Kampot Riverside.jpg','images/Kampot Riverside.jpg',10.6167000,104.1833000,'Always open','Free',NULL,NULL,NULL,NULL,NULL,1,1,3,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,1,1,'relax'),
(21,8,2,'Elephant Valley Project','គម្រោងវិស្ស័យដំរី','An ethical elephant sanctuary where rescued elephants roam freely  observe these gentle giants in their natural highland habitat without riding.','គម្រោងវិស្ស័យដំរី ដែនសត្វដំរីឯកភាពគុណធម៌ដែលដំរីដែលត្រូវបានសង្គ្រោះរស់នៅដោយសេរីភាព មើលដំរីធំៗទន់ភ្លន់នៅក្នុងទីលំនៅដើមភ្នំដោយគ្មានអ្នកជិះ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐘','images/mdlk_elephant_valley.jpg','images/mdlk_elephant_valley.jpg',12.4578000,107.1878000,'Daily tours 7am','$75/day','8',NULL,NULL,NULL,'Moderate',1,1,1,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,1,0,'nature'),
(22,8,2,'Bou Sra Waterfall','ទឹកជ្រោះបូស្រា','One of Cambodia''s most spectacular waterfalls  a twotiered cascade plunging 10m then 25m through highland jungle surrounded by Bunong indigenous villages.','ទឹកជ្រោះបូស្រា ទឹកជ្រោះដ៏អស្ចារ្យមួយនៅកម្ពុជា ជាការធ្លាក់ពីរ ជាន់ ១០ម និង ២៥ម តាមព្រៃភ្នំ ព័ទ្ធដោយភូមិជនជាតិដើមប៊ូណុង។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/mdlk_bou_sra.webp','images/mdlk_bou_sra.webp',12.5000000,107.3500000,'Daily 7am–5pm','$2','3',NULL,NULL,NULL,'Easy',1,1,2,'2026-03-19 13:14:35','near',2.00,5.00,2.0,1,1,0,'nature'),
(23,9,2,'Yeak Laom Crater Lake','បឹងយក្សលោម','A stunning sacred volcanic crater lake of crystalclear blue water set in pristine jungle  one of the most beautiful natural attractions in Cambodia.','បឹងយក្សលោម បឹងភ្នំបុរាណដ៏ស្អាត ទឹកខៀវច្បាស់នៅក្នុងព្រៃស្អាត មួយក្នុងចំណោមទេសភាពធម្មជាតិស្អាតបំផុតនៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌊','images/rnk_yeak_laom.png','images/rnk_yeak_laom.png',13.7461000,107.0069000,'Daily 7am–6pm','$5','2',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,1,0,'nature'),
(24,9,2,'Virachey National Park','ឧទ្យានជាតិវីរចី','Cambodia''s largest national park  a remote wilderness of rivers mountains and ancient forest home to tigers elephants and rare indigenous tribal villages.','ឧទ្យានជាតិវីរចី ឧទ្យានជាតិតំបន់ធំបំផុតនៅកម្ពុជា ព្រៃឆ្ងាយដ៏ស្ងប់ស្ងាត់ មានទន្លេ ភ្នំ និងព្រៃបុរាណ រស់នៅដោយខ្លាឃ្មុំ ដំរី និងភូមិជនជាតិដើមដ៏អស្ចារ្យ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌲','images/rnk_virachey.webp','images/rnk_virachey.webp',14.0000000,107.0000000,'Guided tours only','From $50',NULL,NULL,NULL,NULL,'Challenging',1,1,2,'2026-03-19 13:14:35','near',5.00,5.00,2.0,0,1,0,'nature'),
(25,7,2,'Irrawaddy Dolphins (Kampi Pool)','កាំពី(ត្រីដូហ្វីន)','Watch Cambodia''s critically endangered Irrawaddy dolphins at Kampi  one of the last places on earth where you can observe these rare freshwater dolphins.','កាំពី(ត្រីដូហ្វីន) មើលត្រីដូហ្វីន Irrawaddy ខ្មែរប្រឈមមហានិរន្តនៅកាំពី មួយក្នុងចំនួនកន្លែងចុងក្រោយនៅផែនដីដែលអាចមើលត្រីទឹកស្អាតទាំងនេះ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐬','images/kratie_dolphins.webp','images/kratie_dolphins.webp',12.5667000,106.0167000,'Best: early morning','$9 boat fee','2',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,1,0,'nature'),
(26,7,3,'Koh Trong Island','កោះត្រង','A peaceful rural island in the Mekong river  bicycle around rice paddies visit Cham Muslim villages stay with local families and watch sunsets over the river.','កោះត្រង កោះជនបទស្ងប់ស្ងាត់នៅទន្លេមេគង្គ ជិះកង់ជុំវិញវាលស្រូវ ទស្សនាភូមិមូស្លីមចាម ស្នាក់នៅជាមួយគ្រួសារក្នុងស្រុក និងមើលថ្ងៃលិចលើទន្លេ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌾','images/kratie_koh_trong.jpg','images/kratie_koh_trong.jpg',12.4881000,106.0167000,'Ferry daily','$0.50 ferry',NULL,NULL,NULL,NULL,'Easy',1,1,2,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,1,1,'relax'),
(27,6,7,'Kep Crab Market','ផ្សារក្តាមកែប','The famous seaside crab market where you choose live crabs and have them cooked with Kampot pepper right in front of you  one of Cambodia''s greatest food experiences.','ផ្សារក្តាមកែប ផ្សារក្តាមល្បីនៅឆ្នេរសមុទ្រ ជ្រើសក្តាម ហើយទុកឱ្យចម្អិនជាមួយម្រេចកំពត ជាបទពិសោធន៍ម្ហូបល្អបំផុតមួយនៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦀','images/Kep Crab Market.jpg','images/Kep Crab Market.jpg',10.4833000,104.2833000,'Daily 6am–6pm','Free entry','2',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,0,1,'food'),
(28,6,2,'Kep National Park','ឧទ្យានជាតិកែប','A small but beautiful coastal national park with jungle hiking trails wild monkeys butterflies and panoramic views over the Gulf of Thailand.','ឧទ្យានជាតិកែប ឧទ្យានតូចប៉ុន្តែស្រស់ស្អាតតាមឆ្នេរ មានផ្លូវព្រៃ ខ្លាឃ្មុំ មេអំបៅ និងទិដ្ឋភាពទូលំទូលាយលើសមុទ្រ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦋','images/Kep National Park.webp','images/Kep National Park.webp',10.4833000,104.2833000,'Daily 7am–5pm','$2','3',NULL,NULL,NULL,'Easy',1,1,2,'2026-03-19 13:14:35','near',2.00,5.00,2.0,1,1,0,'nature'),
(29,18,1,'Preah Vihear Temple','ប្រាសាទព្រះវិហារ','A UNESCO World Heritage clifftop temple dramatically perched on the Dangrek Mountains  625m above the Cambodian plains with breathtaking views into Thailand.','ប្រាសាទព្រះវិហារ ប្រាសាទលើចំហៀងភ្នំដង់រែក ៦២៥ម លើដីខ្មែរ មានទិដ្ឋភាពស្រស់ស្អាតចូលថៃ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛩️','images/pvh_temple.webp','images/pvh_temple.webp',14.3928000,104.6786000,'Daily 7:30am–5pm','$10','3',NULL,NULL,NULL,'Moderate',1,1,1,'2026-03-19 13:14:35','near',1.00,5.00,2.0,1,0,0,'culture'),
(30,12,1,'Bamboo Bridge (Kampong Cham)','ស្ពានឬស្សី','The world''s longest bamboo bridge  rebuilt every year by local villagers using ancient techniques crossing the Mekong river to a quiet island village.','ស្ពានឬស្សី ស្ពានឬស្សីវែងបំផុតក្នុងពិភពលោក សង់ឡើងរៀងរាល់ឆ្នាំដោយអ្នកក្នុងភូមិប្រើបច្ចេកវិទ្យាបុរាណ ឆ្លងទន្លែមេគង្គទៅភូមិដាច់ស្ងាត់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎋','images/Bamboo Bridge (Kampong Cham).jpg','images/Bamboo Bridge (Kampong Cham).jpg',11.9939000,105.4640000,'Daily (dry season only)','$0.25','1',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','near',NULL,5.00,2.0,1,0,0,'culture'),
(31,12,1,'Wat Nokor Bachey','វត្តនគរបាជ័យ','An extraordinary fusion temple where a modern Buddhist pagoda has been built inside the walls of an ancient 11thcentury Angkorera temple  unique in Cambodia.','វត្តនគរបាជ័យ ប្រាសាទលាយបញ្ចូលអស្ចារ្យ ដែលវត្តបុទ្ធសាស្ត្រមានរចនាបទសម័យថ្មីសង់នៅក្នុងជញ្ជាំងប្រាសាទអង្គរពីសតវត្សទី១១ ឯកទេសនៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏯','images/Wat Nokor Bachey.webp','images/Wat Nokor Bachey.webp',11.9939000,105.4640000,'Daily 6am–6pm','Free','2',NULL,NULL,NULL,'Easy',1,1,2,'2026-03-19 13:14:35','city',0.00,5.00,2.0,1,0,0,'culture'),
(34,13,1,'Sambor Prei Kuk Temple','ប្រាសាទសំបូរព្រៃគុក','A UNESCO World Heritage preAngkorian temple complex from the 7th century  among the oldest temple ruins in Cambodia set deep in the jungle.','ប្រាសាទសំបូរព្រៃគុក ប្រាសាទមុនអង្គរសម័យទី៧ មួយក្នុងចំណោមប្រាសាទបុរាណបំផុតនៅកម្ពុជា ស្ថិតនៅជ្រៅក្នុងព្រៃ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🗿','images/kthom_sambor_prei_kuk.jpg','images/kthom_sambor_prei_kuk.jpg',12.7800000,104.9700000,'Daily 7am–5pm','$5','4',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,0,0,'culture'),
(35,10,1,'Angkor Borei','អង្គរបូរី','The ancient cradle of Khmer civilization  take a boat through flooded fields to the Angkor Borei museum and the dramatic Phnom Da hilltop temple.','អង្គរបូរី គ្រួសារបុរាណនៃសិល្បៈខ្មែរ ជិះទូកតាមវាលទឹកកកស្ទូច ទៅសារមន្ទីរអង្គរបូរី និងប្រាសាទភ្នំដា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏺','images/takeo_angkor_borei.webp','images/takeo_angkor_borei.webp',10.9908000,104.7850000,'Daily 7am–5pm','$5','4',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-19 13:14:35','near',5.00,5.00,2.0,1,0,0,'culture'),
(38,1,3,'Koh Dach','កោះដាច់','Koh Dach is a peaceful island in the Mekong River located just 15 km from Phnom Penh and is famous for its traditional silkweaving villages and untouched rural Cambodian life.','កោះដាច់ គឺជាកោះដ៏ស្ងប់ស្ងាត់មួយនៅលើទន្លេមេគង្គ ដែលស្ថិតនៅចម្ងាយប្រហែល ១៥ គីឡូម៉ែត្រពីភ្នំពេញ ហើយល្បីល្បាញដោយសារភូមិតម្បាញសូត្រប្រពៃណី និងជីវិតបែបជនបទរបស់ខ្មែរដែលនៅស្ថិតស្ថេរដូចដើម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌾','images/pp_koh_dach.jpg','images/pp_koh_dach.jpg',11.6333000,104.9833000,'Always open','Free ferry','3 hours',NULL,NULL,NULL,'Easy',0,1,8,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,1,'relax'),
(44,2,1,'Banteay Srei Temple','ប្រាសាទបន្ទាយស្រី','The Citadel of Women  a 10thcentury temple famed for extraordinary pink sandstone carvings considered the finest stone carving in all of Southeast Asia.','ប្រាសាទបន្ទាយស្រី ជាវិមានស្ត្រី វត្តសតវត្សទី១០ ដែលល្បីល្បាញសម្រាប់ចម្លាក់ព្រិលពណ៌ផ្កាឈូកល្អឥតខ្ចោះ ដែលគេសរសេរថាជាចម្លាក់ថ្មល្អបំផុតនៅអាស៊ីអាគ្នេយ៍ទាំងមូល។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💎','images/sr_banteay_srei.jpg','images/sr_banteay_srei.jpg',13.5997000,103.9636000,'Daily 7:30am-5:30pm','Included in Angkor Pass','3 hours',NULL,NULL,NULL,'Easy',1,1,6,'2026-03-20 01:55:57','near',NULL,5.00,2.0,1,0,0,'culture'),
(45,2,2,'Phnom Kulen National Park','ឧទ្យានជាតិភ្នំគូលែន','Sacred mountain considered the birthplace of the Khmer Empire. Features the River of a Thousand Lingas beautiful waterfalls and the giant reclining Buddha.','ឯកតាភ្នំគូលែន ជាភ្នំបរិសុទ្ធដែលគេចាត់ទុកជាកន្លែងកំណើតនៃអាណាចក្រខ្មែរ មានទន្លេពាន់លីង កន្លែងទឹកជ្រោះស្រស់ស្អាត និងរូបព្រះពុទ្ធដេកយ៉ាងធំ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏔️','images/sr_phnom_kulen.jpg','images/sr_phnom_kulen.jpg|images/sr_kulen_waterfall.jpg',13.6000000,104.1167000,'Daily 7am-5pm','$20','5 hours',NULL,NULL,NULL,'Moderate',1,1,7,'2026-03-20 01:55:57','near',2.00,5.00,2.0,1,1,0,'nature'),
(46,2,1,'Preah Khan Temple','ប្រាសាទព្រះខ័ន','A vast atmospheric temple dedicated to the father of Jayavarman VII. A labyrinth of corridors galleries and courtyards draped with tree roots and jungle foliage.','ប្រាសាទព្រះខ័ន ជាវត្តធំដែលសហការព្រះបិតានៃជ័យវរ្ម័នទី៧ មានដងផ្លូវជាច្រើន ហាងបង្ហាញ និងវិមានតូចៗ ដែលគ្របដោយឫសឈើ និងព្រៃស្មៅ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌿','images/sr_preah_khan.jpg','images/sr_preah_khan.jpg',13.4428000,103.8558000,'Daily 7:30am-5:30pm','Included in Angkor Pass','3 hours',NULL,NULL,NULL,'Easy',0,1,8,'2026-03-20 01:55:57','near',NULL,5.00,2.0,1,0,0,'culture'),
(47,2,1,'Beng Mealea Temple','ប្រាសាទបឹងមាលា','A remote junglecovered Angkor temple left largely unrestored. Trees vines and moss engulf the sandstone ruins in an incredibly atmospheric setting far from the crowds.','ប្រាសាទបឹងមាលា វត្តអង្គរដែលស្ថិតក្នុងព្រៃឆ្ងាយ និងមិនបានស្តារច្រើន ដើមឈើ ឫសឡើងលើ និងស្មៅគ្របដណ្តប់លើបំណែកថ្ម ស្ថិតនៅក្នុងបរិយាកាសដ៏អស្ចារ្យឆ្ងាយពីមនុស្សច្រើន។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌳','images/sr_beng_mealea.jpg','images/sr_beng_mealea.jpg',13.4578000,104.2247000,'Daily 7am-5pm','$5','3 hours',NULL,NULL,NULL,'Easy',1,1,9,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,0,0,'culture'),
(48,2,7,'Phsar Chas Siem Reap','ផ្សារចាស់សៀមរាប','The historic old market in the heart of Siem Reap overflowing with spices dried fish fresh produce silk and surrounded by great local restaurants.','ផ្សារចាស់សៀមរាប ផ្សារបុរាណនៅចិត្តក្រុងសៀមរាប ពោរពេញដោយគ្រឿងមាស ត្រីស្ងួត ផ្លែឈើ បន្លែស្រស់ សូត្រ និងជុំវិញដោយភោជនីយដ្ឋានក្នុងស្រុកល្អៗ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌶️','images/sr_old_market.jpg','images/sr_old_market.jpg',13.3611000,103.8572000,'Daily 6am-6pm','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,10,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,1,'food'),
(49,2,5,'ATV Quad Biking Rice Fields Siem Reap','ជិះម៉ូតូកង់បួន ATV ក្នុងវាលស្រូវ សៀមរាប','Thrilling ATV rides through Siem Reap countryside past rice paddies ox carts village temples and local farms for an authentic offroad adventure.','ជិះម៉ូតូកង់បួន ATV លើប្រព័ន្ធផ្លូវជនបទសៀមរាប ឆ្លងកាត់វាលស្រូវ រទេះក្រឡុក វត្តភូមិ និងកសិដ្ឋានក្នុងស្រុក សម្រាប់បទពិសោធន៍ off-road ពិតប្រាកដ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏍️','images/sr_atv_biking.jpg','images/sr_atv_biking.jpg',13.3500000,103.8500000,'Daily 7am-5pm','From $35','2 hours',NULL,NULL,NULL,'Easy',0,1,11,'2026-03-20 01:55:57','near',3.00,5.00,2.0,1,0,0,'fun'),
(50,2,2,'Kulen Mountain Waterfall','ទឹកជ្រោះភ្នំគូលែន','A sacred and stunning waterfall cascading over sandstone into a jungle pool. Popular for swimming and picnicking set within the holy Phnom Kulen mountains.','ទឹកជ្រោះភ្នំគូលែន ជាទឹកជ្រោះបរិសុទ្ធ និងស្រស់ស្អាត ជ្រាបលើថ្មច្របល់ចូលទៅក្នុងអាងព្រៃ ពេញនិយមសម្រាប់ហែលទឹក និង អាហារខ្ចប់ នៅភ្នំគូលែនដ៏បរិសុទ្ធ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/sr_kulen_waterfall.jpg','images/sr_kulen_waterfall.jpg|images/sr_phnom_kulen.jpg',13.5978000,104.1183000,'Daily 8am-4pm','Included in park fee','4 hours',NULL,NULL,NULL,'Easy',0,1,12,'2026-03-20 01:55:57','near',NULL,5.00,2.0,1,1,0,'nature'),
(51,2,1,'Angkor National Museum','សារមន្ទីរជាតិអង្គរ','A worldclass museum presenting the history and art of the Khmer Empire with stunning displays of sculptures artifacts and multimedia exhibits about Angkor Wat.','សារមន្ទីរជាតិអង្គរ ជាសារមន្ទីរទូទាំងពិភពលោក បង្ហាញប្រវត្តិ និងសិល្បៈអាណាចក្រខ្មែរ ជាមួយចម្លាក់ សម្ភារៈ និងបង្ហាញ ភាពស្រស់ស្អាត អំពីអង្គរវត្ត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏺','images/sr_angkor_museum.webp','images/sr_angkor_museum.webp',13.3650000,103.8600000,'Daily 8:30am-6pm','$12','2 hours',NULL,NULL,NULL,'Easy',0,1,13,'2026-03-20 01:55:57','near',12.00,5.00,2.0,1,0,0,'culture'),
(52,3,1,'Battambang French Colonial Quarter','អគារបារាំងបាត់ដំបង','The French Colonial Quarter is a walkable heritage area in Battambang city with old architecture, cafes, restaurants, galleries, and riverside street life.','អគារបារាំងបាត់ដំបង អគារបារាំងដែលបានរក្សាទុកយ៉ាងស្អាតតាមបណ្តោយទន្លេ។ ជាឧទាហរណ៍ស្ថាបត្យកម្មវប្បធម៌បារាំងល្អបំផុតនៅកម្ពុជា ដែលមានប្រវត្តិចាប់ពីដើមឆ្នាំ ១៩០០។','Colonial-era architecture · Walkable city heritage · Cafes and restaurants · Photo spots · Riverside atmosphere','ស្ថាបត្យកម្មសម័យអាណានិគម|បេតិកភណ្ឌទីក្រុងសម្រាប់ដើរកម្សាន្ត|កាហ្វេ និងភោជនីយដ្ឋាន|កន្លែងថតរូប|បរិយាកាសមាត់ស្ទឹង','Take a walking tour · Photograph old buildings · Visit cafes and galleries · Pair with the night market','Avoid blocking traffic while taking photos · Respect private buildings · Use sun protection at midday','Morning for cooler walking or late afternoon for soft light.',NULL,'In Battambang city center; walk, bicycle, or tuk-tuk.','🏛️','images/btb_colonial.webp','images/btb_colonial.webp|images/btb1.jpg',13.0957000,103.2022000,'Always open','Free','2 hours','Feature: urban heritage and architecture; best for culture, food, cafes, and photography.','ស្ថាបត្យកម្មបារាំង (ដើមឆ្នាំ ១៩០០)','Walking Tour, Restaurants, Cafes, Photo Spots, Tuk-Tuk Tours','Easy',0,1,5,'2026-03-20 01:55:57','city',0.00,8.00,2.0,1,0,1,'culture,food,art'),
(53,3,2,'Kamping Puoy Reservoir','អាងកំពីងពួយ','A large historic reservoir west of Battambang built during the Khmer Rouge period, now visited for boating, fishing, fresh air and waterside food.','អាងកំពីងពួយ ជាអាងទឹកប្រវត្តិសាស្រ្តខាងលិចក្រុងបាត់ដំបង សាងសង់ក្នុងសម័យប៉ុលពត ហើយបច្ចុប្បន្នមានទេសភាពអាង ទូក ស្ទូចត្រី និងកន្លែងសម្រាកបរិភោគអាហារ។','Historic reservoir; water views; boating; fishing; fresh air; food huts','ទំនប់ប្រវត្តិសាស្រ្ត; ទេសភាពអាង; ជិះទូក; ស្ទូចត្រី; ខ្យល់អាកាសបរិសុទ្ធ; តូបអាហារ','Ride a boat; relax by the water; eat local food; take photos of the reservoir','Avoid swimming in unsafe areas and watch children near water','Dry season afternoon or cool morning','រដូវប្រាំង ពេលល្ងាច ឬពេលព្រឹក','Travel west from Battambang city by tuk-tuk, car or motorbike.','🌊','images/btb/Kamping Puoy Reservoir/2.png','images/btb_kamping_puoy.webp|images/btb3.jpg|images/btb/Kamping Puoy Reservoir/1.png|images/btb/Kamping Puoy Reservoir/2.png|images/btb/Kamping Puoy Reservoir/3.png|images/btb/Kamping Puoy Reservoir/4.jpg|images/btb/Kamping Puoy Reservoir/5.png|images/btb/Kamping Puoy Reservoir/6.jpg|images/btb/Kamping Puoy Reservoir/7.jpg|images/btb/Kamping Puoy Reservoir/8.jpg|images/btb/Kamping Puoy Reservoir/9.jpg|images/btb/Kamping Puoy Reservoir/10.jpg',13.1167000,102.9167000,'Daily','Check locally','2-3 hours','Historic reservoir and water recreation','អាងទឹកប្រវត្តិសាស្រ្ត និងកម្សាន្តលើទឹក','Food &amp; drink / ម្ហូបអាហារ និងភេសជ្ជៈ; rest huts / តូបសម្រាក; boat / ទូក','Easy',1,1,125,'2026-03-20 01:55:57','mid',NULL,6.00,2.5,1,1,1,'nature,relax,water,picnic,food'),
(54,3,7,'Battambang Night Market','ផ្សាររាត្រីបាត់ដំបង','Battambang Night Market is a convenient food stop for street food, BBQ, smoothies, local snacks, and an easy evening walk in the city.','ផ្សាររាត្រីបាត់ដំបង ផ្សារពេលយប់តាមទន្លេមានរសជាតិសម្បូរដោយ សាច់អាំងបែបខ្មែរ ស៊ុយម៉ូទឹកផ្លែឈើស្រស់ នំអាំង និងបង្អែមក្នុងស្រុក។ ជាកន្លែងល្អសម្រាប់រីករាយជាមួយជីវិតយប់នៅបាត់ដំបងពិតប្រាកដ។','Street food and BBQ · Smoothies and drinks · Local snacks · Evening city atmosphere · Easy stop after sightseeing','អាហារតាមផ្លូវ និងសាច់អាំង|ទឹកក្រឡុក និងភេសជ្ជៈ|អាហារសម្រន់ក្នុងស្រុក|បរិយាកាសទីក្រុងពេលល្ងាច|កន្លែងឈប់សម្រាកងាយស្រួលក្រោយដើរលេង','Try Khmer street food · Compare snack stalls · Walk the riverside area · Pair with the colonial quarter','Keep valuables close in crowds · Check prices before ordering · Choose busy, clean stalls','Evening, especially after 5 PM.',NULL,'In Battambang city center; easy by walking, tuk-tuk, or motorbike.','🌙','images/btb_nightmarket.webp','images/btb_nightmarket.webp',13.0957000,103.2022000,'Daily 5pm-11pm','Free','2 hours','Feature: food and market experience; best for dinner, snacks, and local evening atmosphere.','អាំងខ្មែរ ម្ហូបស្ទ្រីត និងទឹកផ្លែឈើស្រស់','Street Food, BBQ, Smoothies, Local Snacks, Drinks','Easy',0,1,7,'2026-03-20 01:55:57','city',0.00,8.00,1.5,1,0,1,'food,nightlife,culture'),
(55,3,1,'Ek Phnom Temple Battambang','ប្រាសាទឯកភ្នំ','An 11th-century temple ruin north of Battambang with ancient carvings, a worship area, ponds and a large Buddha image nearby.','ប្រាសាទឯកភ្នំ ជាប្រាសាទបុរាណសតវត្សទី១១ នៅស្រុកឯកភ្នំ មានសំណង់ថ្មចាស់ ក្បាច់ចម្លាក់ ទីសក្ការៈ គូទឹក និងពុទ្ធបដិមា។','11th-century temple; worship site; ancient stonework; ponds; Buddha image','ប្រាសាទសតវត្សទី១១; ទីសក្ការៈបូជា; សំណង់ថ្មបុរាណ; គូទឹក; ពុទ្ធបដិមា','Visit the temple ruins; photograph carvings; see the nearby pagoda and Buddha image','Respect worship areas and avoid touching fragile carvings','Morning or late afternoon','ពេលព្រឹក ឬល្ងាច','About 12 km from Battambang city in Peam Ek commune.','🏛️','images/btb_ek_phnom.jpg','images/btb_ek_phnom.jpg|images/btb/Ek Phnom Temple Battambang/1.png|images/btb/Ek Phnom Temple Battambang/2.jpg|images/btb/Ek Phnom Temple Battambang/3.jpg|images/btb/Ek Phnom Temple Battambang/4.jpg|images/btb/Ek Phnom Temple Battambang/5.jpg|images/btb/Ek Phnom Temple Battambang/6.jpg|images/btb/Ek Phnom Temple Battambang/7.jpg|images/btb/Ek Phnom Temple Battambang/8.png',13.1850000,103.1950000,'Daily','Check locally','1-2 hours','Ancient temple and Buddha image','ប្រាសាទបុរាណ និងពុទ្ធបដិមា','Food &amp; drink / ម្ហូបអាហារ និងភេសជ្ជៈ; guide / អ្នកណែនាំ','Easy',1,1,121,'2026-03-20 01:55:57','near',NULL,5.00,1.5,1,1,1,'culture,temple,history,religion'),
(56,5,7,'Kampot Pepper Farm Tour','ដំណើរកម្សាន្តចំការម្រេច','Visit a working pepper farm to see how the worldfamous Kampot pepper is grown. Rated the finest pepper in the world by top chefs with tastings and farm purchases.','ដំណើរកម្សាន្តចំការម្រេច ទៅមើលចំការម្រេចយល់ដឹងពីការដំណើរការ ដើម្បីឃើញវិធីដាំម្រេចកំពតល្បីល្បាញលើពិភពលោក និងតម្លៃល្អបំផុត',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌶️','images/Kampot Pepper Farm Tour.jpg','images/Kampot Pepper Farm Tour.jpg',10.6167000,104.1833000,'Daily 8am-5pm','Free-$5','2 hours',NULL,NULL,NULL,'Easy',1,1,4,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,1,'food'),
(57,5,3,'Kampot River Kayaking','ការជិះទូកកាយ៉ាក់ទន្លេកំពត','Paddle through mangroves and along the Kampot River at sunset. One of the most peaceful experiences in Cambodia passing firefly trees at dusk.','ការជិះទូកកាយ៉ាក់ទន្លេកំពត ជិះទូកតាមព្រៃទឹក និងតាមទន្លេកំពតពេលថ្ងៃលិច។ បទពិសោធន៍ស្ងប់ស្ងាត់បំផុតនៅកម្ពុជា ឆ្លងកាត់ដើមអន្លង់ពេលលិច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚣','images/Kampot River Kayaking.jpg','images/Kampot River Kayaking.jpg',10.6167000,104.1833000,'Daily tours','From $15','3 hours',NULL,NULL,NULL,'Easy',0,1,5,'2026-03-20 01:55:57','near',1.00,5.00,2.0,1,1,1,'relax'),
(58,5,2,'Teuk Chhou Rapids','ទឹកឈូកំពត','A popular local swimming and picnic spot where the Kampot River rushes over rocky rapids. Beautiful on weekends when Cambodian families come to swim and barbecue.','ទឹកឈូកំពត កន្លែងហែលទឹក និង picnic ក្នុងស្រុកពេញនិយម ទន្លេកំពតរត់លើថ្មទឹកជ្រោះ។ ស្អាតពេលចុងសប្តាហ៍ពេលគ្រួសារខ្មែរមកហែល និងធ្វើ BBQ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Teuk Chhou Rapids.jpg','images/Teuk Chhou Rapids.jpg',10.6500000,104.2000000,'Always open','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,6,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,0,'nature'),
(59,4,6,'Independence Beach Sihanoukville','ឆ្នេរឯករាជ្យ','A long quieter beach near the Independence Hotel. Popular for morning swimming and sunset walks with cleaner water than many other Sihanoukville beaches.','ឆ្នេរឯករាជ្យ ឆ្នេរលំបាក និងស្ងប់ស្ងាត់ជិតសណ្ឋាគារឯករាជ្យ។ ពេញនិយមសម្រាប់ហែលទឹកព្រឹក និងដើរលេងថ្ងៃលិច ជាមួយទឹកស្អាតជាងឆ្នេរផ្សេងៗនៅព្រះសីហនុ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌊','images/Independence Beach Sihanoukville.jpg','images/Independence Beach Sihanoukville.jpg',10.6050000,103.5200000,'Always open','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,0,'beach'),
(60,4,2,'Ream National Park','ឧទ្យានជាតិរាម','A stunning coastal national park with mangrove forests pristine beaches dolphins and trekking trails. One of Cambodia most biodiverse protected areas on the coast.','ឧទ្យានជាតិរាម ឧទ្យានជាតិមានឆ្នេរស្រស់ស្អាត មានព្រៃទឹកខ្មៅ ឆ្នេរស្អាត ដូង និងមាគ៌ាកាត់ព្រៃ។ ជាភាគីដែលមានជីវចម្រុះដ៏ច្រើនបំផុតនៅតំបន់ឆ្នេរខ្មែរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌴','images/Ream National Park.webp','images/Ream National Park.webp',10.5000000,103.6500000,'Daily 7am-5pm','$5','4 hours',NULL,NULL,NULL,'Moderate',1,1,5,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,1,0,'nature'),
(62,8,2,'Sen Monorom Town Viewpoints','ទីក្រុងសែនមនោរម្យ','The charming capital of Mondulkiri. A highland town with rolling green hills pine forests mistcovered mornings and stunning panoramic viewpoints over the jungle.','ទីក្រុងសែនមនោរម្យ រដ្ឋធានីដ៏មានមោទនភាពនៃមណ្ឌលគីរី ក្រុងភ្នំជាមួយត្បូងស្មៅអស្ចារ្យ ព្រៃស្រល់ ពេលព្រឹកមានពពកចម្រុះ និងទិដ្ឋភាពទូលំទូលាយលើព្រៃ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌄','images/mdlk_sen_monorom.webp','images/mdlk_sen_monorom.webp',12.4578000,107.1878000,'Always open','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,0,'nature'),
(63,8,1,'Bunong Indigenous Village Mondulkiri','ភូមិ Bunong ជនជាតិដើម','Visit an authentic Bunong indigenous village. Learn about traditional animist culture bamboo house construction forest medicine and the deep connection to nature.','ភូមិ Bunong ជនជាតិដើម ទស្សនាភូមិជនជាតិដើមប៊ូណុងពិតប្រាកដ សិក្សាវប្បធម៌អាណិមីស សំណង់ផ្ទះកូនឈើ វេជ្ជសាស្រ្តព្រៃ និងការតភ្ជាប់ជ្រាលជ្រៅជាមួយធម្មជាតិ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏕️','images/mdlk_bunong_village.jpg','images/mdlk_bunong_village.jpg',12.6000000,107.3000000,'Guided tours only','From $20','4 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','near',2.00,5.00,2.0,1,0,0,'culture'),
(64,8,4,'Mondulkiri Jungle Trekking','ដើរព្រៃ មណ្ឌលគីរី','Multiday jungle treks through Mondulkiri highland forests. Spot wildlife cross rivers sleep in jungle camps and experience untouched wilderness.','ដើរព្រៃ មណ្ឌលគីរី ដំណើរដើរព្រៃជាច្រើនថ្ងៃតាមព្រៃភ្នំមណ្ឌលគីរី មើលសត្វព្រៃ ឆ្លងទន្លេ នៃស្នាក់នៅជម្រកក្នុងព្រៃ និងបទពិសោធន៍ព្រៃអង្គុយមិនបាន។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🥾','images/mdlk_jungle_trekking.jpg','images/mdlk_jungle_trekking.jpg',12.4578000,107.1878000,'Guided tours only','From $60 per day',NULL,NULL,NULL,NULL,'Challenging',0,1,5,'2026-03-20 01:55:57','near',6.00,5.00,2.0,0,1,0,'mountain'),
(65,9,2,'Ka Tieng Waterfall Ratanakiri','ទឹកជ្រោះ Ka Tieng','A beautiful remote waterfall deep in Ratanakiri jungle. A rewarding trek through indigenous villages and dense forest to reach this cascading hidden gem.','ទឹកជ្រោះ Ka Tieng ទឹកជ្រោះស្រស់ស្អាតនៅឆ្ងាយក្នុងព្រៃរតនគិរី ធ្វើដំណើរដើរតាមភូមិជនជាតិដើម និងព្រៃកណ្ដាលដើម្បីទៅទឹកជ្រោះលាក់បំពួនយ៉ាងស្រស់ស្អាត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/rnk_ka_tieng.jpg','images/rnk_ka_tieng.jpg',13.5500000,107.1000000,'Daily 7am-5pm','$2','4 hours',NULL,NULL,NULL,'Moderate',0,1,3,'2026-03-20 01:55:57','near',2.00,5.00,2.0,1,1,0,'nature'),
(66,9,1,'Ban Lung Town Gem Markets','ផ្សារគ្រឿងអលង្ការជាតំបន់ទីក្រុងបាលុង','The frontier capital of Ratanakiri. Famous for gem trading zircon and ruby mining and as the gateway to the province jungle trekking and waterfall adventures.','ផ្សារគ្រឿងអលង្ការជាតំបន់ទីក្រុងបាលុង រាជធានីខាងប្រព័ន្ធរតនគិរី ល្បីល្បាញក្នុងការជួញដូរ រ៉ូហ្សឺ និងមន្ត្រីក្រហម និងជាតំបន់ចូលទៅការដើរព្រៃ និងទឹកជ្រោះក្នុងខេត្ត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💎','images/rnk_ban_lung.jpg','images/rnk_ban_lung.jpg',13.7394000,107.0050000,'Daily','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,0,'culture'),
(68,7,2,'Mekong Discovery Trail Kratie','ផ្លូវវប្បធម៌ Mekong','A scenic cycling and kayaking trail along the Mekong. Pass rice paddy villages floating fish farms Cham Muslim communities and beautiful river islands.','ផ្លូវវប្បធម៌ Mekong ផ្លូវជិះកង់ និងកាយ៉ាក់មានទេសភាពល្អតាមទន្លេមេគង្គ ឆ្លងកាត់ភូមិវាលស្រូវ ចំការលក់ត្រីអណ្តែត សហគមន៍មូស្លីមចាម និងកោះទន្លេស្អាត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚴','images/kratie_discovery_trail.jpg','images/kratie_discovery_trail.jpg',12.5000000,106.0000000,'Always open','Free','4 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,0,'nature'),
(69,6,3,'Kep Beach and Promenade','ឆ្នេរកែប','A quiet charming beach town with a beautiful promenade lined with old French villas. Perfect for a relaxed morning walk or watching fishing boats at sunset.','ឆ្នេរកែប ក្រុងឆ្នេរស្ងប់ស្ងាត់ និងមានមោទនភាព មានផ្លូវដើរដ៏ស្រស់ស្អាតជាប់វីឡាបារាំងចាស់។ ល្អសម្រាប់ដើរព្រឹកស្ងប់ស្ងាត់ ឬមើលទូកនេសាទពេលថ្ងៃលិច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/Kep Beach and Promenade.jpg','images/Kep Beach and Promenade.jpg',10.4833000,104.2833000,'Always open','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,1,'relax'),
(70,6,6,'Koh Tonsay','កោះទន្សាយ','A tiny rustic island 20 minutes by boat from Kep. Pristine white sand beaches hammock bungalows no cars no WiFi just jungle beach and fresh seafood.','កោះទន្សាយ កោះតូច ធ្វើដំណើររយៈពេល ២០នាទីជិតកែប មានឆ្នេរស្មៅស្រស់ស្អាត ផ្ទះលំហែរ ខ្សាច់ គ្មានរថយន្ត គ្មាន Wi-Fi មានតែព្រៃ ឆ្នេរ និងសមុទ្រថ្មី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐰','images/Rabbit Island Koh Tonsay.jpg','images/Rabbit Island Koh Tonsay.jpg',10.4500000,104.3167000,'Boats daily','$6 return',NULL,NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','near',6.00,5.00,2.0,1,0,0,'beach'),
(72,12,1,'Phnom Pros and Phnom Srei','ភ្នំប្រុស និង ភ្នំស្រី','Two legendary hills called Man Mountain and Woman Mountain with pagodas monkeys and a fascinating local legend about a race to determine marriage customs.','ភ្នំប្រុស និង ភ្នំស្រី ភ្នំទាំងពីរល្បីឈ្មោះភ្នំប្រុស និងភ្នំស្រី មានវត្ត មក្សេ និងព្រលឹងប្រពៃណីអស្ចារ្យអំពីការប្រណាំងកំណត់ប្រពៃណីមង្គលការ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛰️','images/Phnom Pros and Phnom Srei.jpg','images/Phnom Pros and Phnom Srei.jpg',11.9939000,105.4640000,'Daily 6am-6pm','$1','2 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','near',1.00,5.00,2.0,1,0,0,'culture'),
(73,13,2,'Stung Sen River Floating Villages','ភូមិអណ្តែតស្ទឹងសែន','The gentle Stung Sen river flows through Kampong Thom. Beautiful boat rides past floating villages rice fields and traditional riverside Khmer life.','ភូមិអណ្តែតស្ទឹងសែន ទន្លេស្ទឹងសែនស្ងប់ស្ងាត់ឆ្លងតាមកំពង់ធំ ជិះទូកតាមភូមិអណ្តែត វាលអង្ករ និងជីវិតមាត់ទន្លេ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚤','images/kthom_stung_sen.jpg','images/kthom_stung_sen.jpg',12.7111000,104.8897000,'Daily boat tours','From $10','2 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','near',1.00,5.00,2.0,1,1,0,'nature'),
(74,13,1,'Prasat Andet Pre-Angkorian Temple','ប្រាសាទអណ្ឌិត ប្រាសាទមុនអង្គរ','A rarely visited preAngkorian temple from the 7th century in a remote jungle clearing. One of Cambodia hidden archaeological gems with exquisite early Khmer carvings.','ប្រាសាទអណ្ឌិត ប្រាសាទមុនអង្គរពីសតវត្សទី៧ មានភ្ញៀវទេសចរតិចតួច ស្ថិតនៅក្នុងព្រៃឆ្ងាយ មួយក្នុងចំណោមរ៉ូប៊ីនអាណាគរជ្រៅរបស់ខ្មែរដែលមានស្នាដៃសិល្បៈល្អ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🗿','images/kthom_prasat_andet.png','images/kthom_prasat_andet.png',12.7500000,105.1000000,'Daily 7am-5pm','$2','2 hours',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-20 01:55:57','near',2.00,5.00,2.0,1,0,0,'culture'),
(75,10,4,'Phnom Chisor Hilltop Temple','ប្រាសាទភ្នំជីស័រ','A 11thcentury hilltop Angkor temple with sweeping views over the Takeo plains. 480 steps lead to ruins and a working Buddhist pagoda with incredible panoramic vistas.','ប្រាសាទភ្នំជីស័រ ប្រាសាទអង្គរពីសតវត្សទី១១ នៅកំពូលភ្នំ ទិដ្ឋភាពទូលំទូលាយលើវាលតាកែវ ជំហាន ៤៨០ ដឹកទៅប្រាសាទខូច និងវត្តបុទ្ធសកម្ម ជាមួយទិដ្ឋភាពអស្ចារ្យ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛩️','images/takeo_phnom_chisor.jpg','images/takeo_phnom_chisor.jpg',11.3072000,104.7833000,'Daily 7am-5pm','$3','2 hours',NULL,NULL,NULL,'Moderate',1,1,2,'2026-03-20 01:55:57','near',3.00,5.00,2.0,1,1,0,'mountain'),
(78,11,1,'Kandal Silk Weaving Villages','ភូមិតំបាញក្រណាត់សូត្រកណ្ដាល','Traditional silk weaving villages where master weavers still create intricate Khmer silk patterns on hand looms that have been passed down for generations.','ភូមិតំបាញក្រណាត់សូត្រកណ្ដាល ភូមិចងក្រណាត់សូត្រប្រពៃណី ដែលអ្នកចងសូត្រមានជំនាញបង្កើតលំនាំសូត្រខ្មែរលំអិតលើចង្ក្រានដៃដែលបន្តមកពីជំនាន់មុន។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🧵','images/kandal_silk_weaving.jpg','images/kandal_silk_weaving.jpg',11.3000000,105.0500000,'Daily 8am-5pm','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,0,'culture'),
(79,14,4,'Phnom Aural Cambodia Highest Peak','ភ្នំអូរ៉ាល់','Cambodia highest mountain at 1813m. A challenging multiday trek through pristine Cardamom Mountain wilderness to reach the cloudcovered summit.','ភ្នំអូរ៉ាល់ ភ្នំខ្ពស់បំផុតនៅកម្ពុជា ១៨១៣ម ដំណើរឡើងភ្នំប៉ះព្រៃកាដាមូមធម្មជាតិច្រើនថ្ងៃដើម្បីឈានដល់កំពូលដែលគ្របដណ្តប់ដោយពពក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏔️','images/kspeu_phnom_aural.jpg','images/kspeu_phnom_aural.jpg',11.9833000,104.1667000,'Guided treks only','From $80',NULL,NULL,NULL,NULL,'Challenging',1,1,1,'2026-03-20 01:55:57','near',NULL,5.00,2.0,0,1,0,'mountain'),
(80,14,2,'Kirirom National Park','ឧទ្យានជាតិគីរីរម្យ','Cambodia first national park. Cool highland pine forests at 700m elevation beautiful waterfalls deer and the unique chance to experience a cooler climate.','ឧទ្យានជាតិគីរីរម្យ ឧទ្យានជាតិដំបូងរបស់កម្ពុជា ព្រៃស្រល់ខ្ពស់ ៧០០ម ទឹកជ្រោះស្អាត និងឱកាសឯកសិទ្ធិសម្រាប់ទទួលបទពិសោធន៍អាកាសធាតុត្រជាក់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌲','images/kspeu_kirirom.jpg','images/kspeu_kirirom.jpg',11.3667000,104.0833000,'Daily 7am-5pm','$5','4 hours',NULL,NULL,NULL,'Moderate',1,1,2,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,1,0,'nature'),
(81,14,2,'Tatai Waterfall Cardamom Mountains','ទឹកជ្រោះតាតៃ','A beautiful multitiered waterfall on the edge of the Cardamom Mountains. A great day trip from Phnom Penh with natural swimming pools and jungle scenery.','ទឹកជ្រោះតាតៃ ទឹកជ្រោះច្រើនជាន់ស្រស់ស្អាតនៅគែមភ្នំកាដាមូម ដំណើរថ្ងៃល្អពីភ្នំពេញ ជាមួយអាងហែលទឹកធម្មជាតិ និងទេសភាពព្រៃឈើ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/kspeu_tatai_waterfall.webp','images/kspeu_tatai_waterfall.webp',11.5000000,104.2000000,'Daily 7am-5pm','$3','3 hours',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-20 01:55:57','near',3.00,5.00,2.0,1,1,0,'nature'),
(82,15,1,'Floating Villages on Tonle Sap','ភូមិអណ្ដែតទឹក','Experience authentic floating village life on Cambodia great lake. Entire communities live on water with floating schools churches markets and fish farms.','ភូមិអណ្ដែតទឹក ទទួលបទពិសោធន៍ជីវិតភូមិអណ្ដែតលើសមុទ្រធំកម្ពុជា សហគមន៍រស់នៅលើទឹក មានសាលា វិហារ ផ្សារ និងកសិដ្ឋានត្រី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏘️','images/kchnang_floating_village.jpg','images/kchnang_floating_village.jpg',12.2500000,104.6667000,'Boat tours daily','From $10','3 hours',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-20 01:55:57','near',1.00,5.00,2.0,1,0,0,'culture'),
(85,16,2,'Tonle Sap Birdwatching Pursat','ការសង្កេតបក្សី Tonle Sap','Flooded forests along Pursat Tonle Sap shoreline are a worldclass birdwatching destination. Spot painted storks pelicans cormorants and rare waterbirds.','ការសង្កេតបក្សី ទន្លេសាប ព្រៃជ្រលងទឹកតាមឆ្នេរស្រុកពោធិ៍សាត់ ល្បីសម្រាប់មើលបក្សីក្នុងពិភពលោក មើលសត្វស្ទកប៉ុន បែលីកាន់ កូម៉រ៉ង់ និងបក្សីទឹកកម្រ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦅','images/Tonle Sap Birdwatching Pursat.jpeg','images/Tonle Sap Birdwatching Pursat.jpeg',12.5000000,103.9000000,'Daily dawn-dusk','Guide fees','3 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','near',NULL,5.00,2.0,1,1,0,'nature'),
(86,18,1,'Koh Ker Pyramid Temple Complex','ប្រាសាទកោះកែរ','A remote 10thcentury royal capital with over 100 temples. The centerpiece is a 7tiered pyramid temple rising 35m above the jungle rivaling Angkor Wat in grandeur.','ប្រាសាទកោះកែរ រាជធានីទី១០ នៅឆ្ងាយ មានប្រាសាទ ១០០+ ប្រាសាទកណ្ដាល ជាប្រាសាទប៉ារ៉ាមីត ៧ជាន់ឡើង ៣៥ម លើព្រៃ ដល់កម្រិតអង្គរវត្ត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏛️','images/pvh_koh_ker.jpg','images/pvh_koh_ker.jpg|images/pvh_temple.webp',13.7903000,104.5644000,'Daily 7am-5pm','$10','4 hours',NULL,NULL,NULL,'Easy',1,1,2,'2026-03-20 01:55:57','near',1.00,5.00,2.0,1,0,0,'culture'),
(87,18,2,'Preah Vihear Wildlife Sanctuary','ឧទ្យានសត្វ ព្រះវិហារ','A vast remote wildlife sanctuary in northern Cambodia home to wild elephants tigers pileated gibbons and some of the last pristine dry forests.','ឧទ្យានសត្វ ព្រះវិហារ ដែនសត្វព្រៃធំឆ្ងាយភាគខាងជើងកម្ពុជា មានដំរីព្រៃ ខ្លាឃ្មុំ កីប៉ុង និងព្រៃស្ងួតដ៏ស្អាតចុងក្រោយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐘','images/pvh_wildlife.webp','images/pvh_wildlife.webp',14.0000000,104.7000000,'Guided only','From $50',NULL,NULL,NULL,NULL,'Challenging',0,1,3,'2026-03-20 01:55:57','near',5.00,5.00,2.0,0,1,0,'nature'),
(90,20,1,'Neak Loeung River Town','ទន្លេអ្នកលឿង','Historic Mekong river crossing town and the site of a famous 1973 wartime incident. Now a peaceful ferry point with riverside restaurants and authentic Cambodian life.','ទន្លេអ្នកលឿង ទីក្រុងប្រវត្តិសាស្ត្រឆ្លងទន្លេមេគង្គ និងកន្លែងព្រឹត្តិការណ៍សង្គ្រាម ១៩៧៣ ឥឡូវជាកន្លែងទំនេរពេលជិះទូក មានភោជនីយដ្ឋានមាត់ទន្លេ និងជីវិតពិតប្រាកដ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛴️','images/pveng_neak_loeung.jpg','images/pveng_neak_loeung.jpg',11.4833000,105.3167000,'Always open','Ferry fee','1 hour',NULL,NULL,NULL,'Easy',0,1,1,'2026-03-20 01:55:57','near',NULL,5.00,2.0,1,0,0,'culture'),
(91,20,8,'Prey Veng Riverside Pagodas','វត្តទន្លេ ព្រៃវែង','A series of beautiful riverside pagodas with traditional Khmer architecture colorful murals depicting Buddhist stories and peaceful meditation gardens.','វត្តទន្លេ ព្រៃវែង វត្តស្អាតៗនៅមាត់ទន្លេ មានស្ថាបត្យកម្មខ្មែរ គំនូរជាច្រើនពណ៌បង្ហាញរឿងបុទ្ធសាស្ត្រ និងសួនធម្មជាតិស្ងប់ស្ងាត់សម្រាប់រៀនធម៌។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🙏','images/pveng_pagodas.jpg','images/pveng_pagodas.jpg',11.4833000,105.3167000,'Daily 5am-6pm','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,0,'religious'),
(93,21,7,'Svay Rieng Border River Seafood','ម្ហូបសមុទ្រតាមឆ្នេរសមុទ្រ','Fresh river fish restaurants along the Mekong border. Sample unique CambodianVietnamese border cuisine including giant river prawns and exotic freshwater fish.','ម្ហូបសមុទ្រតាមឆ្នេរសមុទ្រ ភោជនីយដ្ឋានត្រីស្រស់នៅមាត់ទន្លេមេគង្គ សាករសជាតិម្ហូបព្រំដែនខ្មែរ-វៀតណាម រួមមានដំរីធំ និងត្រីទឹកផ្អែមអស្ចារ្យ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐟','images/srieng_seafood.jpg','images/srieng_seafood.jpg',11.0878000,105.7997000,'Daily 6am-10pm','Free entry','2 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,1,'food'),
(94,23,1,'Banteay Chhmar Temple Complex','ប្រាសាទបន្ទាយឆ្មារ','A vast remote Angkorera temple complex. One of the largest in Cambodia after Angkor Wat featuring extraordinary basreliefs and multifaced towers completely off the tourist trail.','ប្រាសាទបន្ទាយឆ្មារ ស្ថាបត្យកម្មប្រាសាទអង្គរបុរាណធំឆ្ងាយ មួយក្នុងចំណោមប្រាសាទធំបំផុតក្រោយអង្គរវត្ត មានរូបសំណាកល្អឥតខ្ចោះ និងការរចនាតួជាច្រើន ចេញពីផ្លូវទេសចរណ៍។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏛️','images/Banteay Chhmar Temple Complex.jpg','images/Banteay Chhmar Temple Complex.jpg',13.9333000,102.9833000,'Daily 7am-5pm','$5','4 hours',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,0,0,'culture'),
(95,23,5,'Poipet Border Casino Town','កាស៊ីណូព្រំដែនប៉ោយប៉ែត','Cambodia bustling border city with Thailand. Lined with casinos hotels and markets overflowing with goods from both countries in a fascinating border culture.','កាស៊ីណូព្រំដែនប៉ោយប៉ែត ទីក្រុងព្រំដែនរវាងកម្ពុជា និងថៃ(សៀម) តំបន់ភោជនីយដ្ឋាន សណ្ឋាគារ និងផ្សារដែលពោរពេញទំនិញពីទាំងពីរប្រទេស មានវប្បធម៌ព្រំដែនចំរូងចំរាស្រ្ត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎰','images/Poipet Border Casino Town.jpg','images/Poipet Border Casino Town.jpg',13.6553000,102.5572000,'24 hours','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,0,0,'fun'),
(97,22,4,'Phnom Yat Sacred Mountain Pailin','ភ្នំយ៉ាត','A sacred mountain rising above Pailin town with a beautiful pagoda at the summit. Climb through jungle trails past meditation caves for panoramic views over Thailand.','ភ្នំយ៉ាត ភ្នំបរិញ្ញាណលើទីក្រុងប៉ៃលិន មានបូដ្ឋសាលាស្រស់ស្អាតនៅកំពូល ជិះតាមផ្លូវព្រៃ និងសម្រាកសម្រាប់ទិដ្ឋភាពទូលំទូលាយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛰️','images/Phnom Yat Sacred Mountain Pailin.jpg','images/Phnom Yat Sacred Mountain Pailin.jpg',12.8500000,102.6167000,'Daily 6am-6pm','Free','2 hours',NULL,NULL,NULL,'Moderate',0,1,2,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,0,'mountain'),
(98,17,4,'Dangrek Mountain Viewpoints','ភ្នំដង់រែក','Dramatic viewpoints over the Dangrek mountain escarpment into Thailand. A stunning border landscape with sweeping views stretching for hundreds of kilometers.','ភ្នំដង់រែក ទិដ្ឋភាពទាក់ទាញលើភ្នំដង់រែកចូលថៃ ទេសភាពព្រំដែនអស្ចារ្យទូលំទូលាយរហូតដល់រយគីឡូម៉ែត្រ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌄','images/oddar_dangrek.jpg','images/oddar_dangrek.jpg',14.2000000,103.7000000,'Always open','Free','2 hours',NULL,NULL,NULL,'Easy',0,1,1,'2026-03-20 01:55:57','city',0.00,5.00,2.0,1,1,0,'mountain'),
(99,17,1,'Anlong Veng Historical Site','អន្លង់វែង','The last stronghold of the Khmer Rouge regime. Visit the grave of Pol Pot the house of Ta Mok and learn about the final chapter of Cambodia darkest period.','អន្លង់វែង ក្បួនចុងក្រោយនៃរបបខ្មែរក្រហម មើលសារមន្ទីរពុលពត ផ្ទះតាមុក និងសិក្សាបទបញ្ចប់របបអំពីរឿងអុជ្រិយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕯️','images/oddar_anlong_veng.webp','images/oddar_anlong_veng.webp',14.1800000,103.5200000,'Daily 7am-5pm','$5','3 hours',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,0,0,'culture'),
(103,25,2,'Peam Krasaop Mangrove Sanctuary','ព្រៃកោងកាង','A vast mangrove forest accessible by boardwalk and boat. Home to sea horses crabs birds and the fascinating ecosystem where the jungle meets the sea.','ព្រៃកោងកាង ព្រៃម៉ង់ក្រោវធំ ចូលបានតាមស្ពានដើរ និងទូក មានសេះសមុទ្រ ក្រពើ បក្សី និងប្រព័ន្ធអេកូស៊ីស្ទើមពិសេសពេលព្រៃជួបសមុទ្រ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦀','images/Peam Krasaop Mangrove Sanctuary.jpg','images/Peam Krasaop Mangrove Sanctuary.jpg',11.5500000,103.0000000,'Daily 7am-5pm','$5','3 hours',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-20 01:55:57','near',5.00,5.00,2.0,1,1,0,'nature'),
(111,11,2,'Phnom Tamao Wildlife Rescue Center','មជ្ឈមណ្ឌលសត្វព្រៃភ្នំតាមៅ','The largest wildlife sanctuary in Cambodia  home to rescued sun bears tigers elephants and gibbons in spacious natural habitats. A worldclass conservation center.','មជ្ឈមណ្ឌលសត្វព្រៃភ្នំតាមៅ ដែនសត្វព្រៃធំបំផុតនៅកម្ពុជា រស់នៅដោយខ្លាឃ្មុំព្រះអាទិត្យ ខ្លាឃ្មុំខ្មៅ ដំរី និងកីប៉ុងក្នុងទីលំនៅធម្មជាតិទូលំទូលាយ ជាមជ្ឈមណ្ឌលអភិរក្សកម្រិតពិភពលោក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐯','images/Phnom Tamao Wildlife Rescue Center.jpg','images/Phnom Tamao Wildlife Rescue Center.jpg',NULL,NULL,'Daily 8am-5pm','$5','4',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-21 13:49:19','near',5.00,5.00,2.0,1,1,0,'nature'),
(113,11,7,'Prek Eng Floating Restaurants','ភោជនីយដ្ឋានអណ្តែតព្រេកអែង','Famous riverside floating restaurants near Phnom Penh serving the freshest fish dishes  a beloved weekend escape for locals craving authentic Khmer river food.','ភោជនីយដ្ឋានអណ្តែតព្រេកអែង ភោជនីយដ្ឋានអណ្តែតល្បីនៅជិតភ្នំពេញ ផ្ដល់មុខម្ហូបត្រីថ្មីៗ ជាកន្លែងចូលរួមចុងសប្តាហ៍ដែលសម្រាប់អ្នកក្នុងស្រុកចង់សាករសជាតិម្ហូបទន្លេខ្មែរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐟','images/Prek Eng Floating Restaurants.jpg','images/Prek Eng Floating Restaurants.jpg',NULL,NULL,'Daily 10am-9pm','Free entry','2',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,1,'food'),
(114,11,3,'Countryside Cycling Kandal','ជិះកង់ជនបទ','Peaceful cycling routes through Kandal rice paddies riverside villages and traditional wooden houses  a perfect day trip from Phnom Penh into rural Cambodia.','ជិះកង់ជនបទ ផ្លូវជិះកង់ស្ងប់ស្ងាត់តាមវាលស្រែកណ្ដាល ភូមិមាត់ទន្លេ និងផ្ទះឈើបែបប្រពៃណី ដំណើរថ្ងៃល្អពីភ្នំពេញចូលជនបទខ្មែរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚴','images/Countryside Cycling Kandal.jpg','images/Countryside Cycling Kandal.jpg',NULL,NULL,'Always open','Free','4',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,1,'relax'),
(116,10,3,'Takeo Lake Boat Rides','ការជិះទូកនៅបឹងតាកែវ','A vast scenic lake in the heart of Takeo town  hire a boat to drift through lotus flowers watch local fishermen cast nets and enjoy the peaceful countryside scenery.','ការជិះទូកនៅបឹងតាកែវ បឹងធំស្រស់ស្អាតនៅចំណុចកណ្តាលទីក្រុងតាកែវ ជិះទូកកាត់តាមផ្កាឈូក មើលអ្នកនេសាទក្នុងស្រុកចាក់បណ្ណ និងរីករាយទេសភាពជនបទស្ងប់ស្ងាត់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚣','images/Takeo Lake Boat Rides.jpg','images/Takeo Lake Boat Rides.jpg',NULL,NULL,'Daily 6am-6pm','From $3','2',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-21 13:49:19','near',3.00,5.00,2.0,1,1,1,'relax'),
(117,10,1,'Neang Khmao Temple','ប្រាសាទនាងខ្មៅ','A mysterious and rarely visited ancient temple complex in the Takeo countryside  atmospheric ruins with carved lintels crumbling towers and very few tourists.','ប្រាសាទនាងខ្មៅ ប្រាសាទបុរាណល្បីនាពេលល្ងាច និងមនាតិចតួចនូវភ្ញៀវទេសចរ នៅជនបទតាកែវ ប្រាសាទខូចមាន អាកាសធាតុស្ងប់ស្ងាត់ ទ្វារចាក់សោ មេឃស្រអាប់និងអ្នកទេសចរតិចតួច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🗿','images/Neang Khmao Temple.jpg','images/Neang Khmao Temple.jpg',NULL,NULL,'Always open','Free','2',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'culture'),
(118,5,2,'Kampot Salt Fields','វាលអំបិល','Vast white salt fields stretching to the horizon  watch workers harvest sea salt using traditional methods passed down for generations along the Kampot coast.','វាលអំបិល វាលអំបិលពណ៌សធំៗដល់ដងទឹក មើលកម្មករចម្រាញ់អំបិលដោយវិធីប្រពៃណី ដែលបន្តពីជំនាន់មួយទៅមួយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🧂','images/Kampot Salt Fields.avif','images/Kampot Salt Fields.avif',NULL,NULL,'Best: Nov-May','Free','2',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,0,'nature'),
(119,5,2,'Secret Lake Kampot','បឹងអាថ៌កំបាំង','A hidden freshwater lake tucked in the Kampot countryside  a local secret for swimming kayaking and picnicking surrounded by palm trees and rice fields.','បឹងអាថ៌កំបាំង បឹងទឹកស្រស់ស្អាតលាក់នៅជនបទកំពត ជារឿងសម្ងាត់ក្នុងស្រុក សម្រាប់ហែលទឹក ជិះកាយ៉ាក់ និង picnic ជុំវិញដើមត្នោត និងវាលស្រូវ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏊','images/Secret Lake Kampot.jpg','images/Secret Lake Kampot.jpg',NULL,NULL,'Always open','Free','3',NULL,NULL,NULL,'Easy',0,1,8,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,0,'nature'),
(120,6,3,'Sunset at Kep Beach','ព្រះអាទិត្យលិចកែប','The most peaceful sunset spot on the Cambodian coast  watch the sky turn gold and red over the Gulf of Thailand from Kep beach promenade.','ព្រះអាទិត្យលិចកែប កន្លែងថ្ងៃលិចស្ងប់ស្ងាត់បំផុតនៅឆ្នេរកម្ពុជា មើលមេឃប្រែទៅពណ៌មាស និងក្រហមលើសមុទ្រថៃ(សៀម) ពីផ្លូវដើរឆ្នេរកែប។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/Sunset at Kep Beach.jpg','images/Sunset at Kep Beach.jpg',NULL,NULL,'Daily evenings','Free','1',NULL,NULL,NULL,'Easy',0,1,5,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,1,'relax'),
(122,7,3,'Mekong River Sunset Kratie','ព្រះអាទិត្យលិចនៅមេគង្គ','The most beautiful Mekong sunsets in Cambodia  sit at a riverside cafe in Kratie and watch the sky ablaze over the wide river as fishing boats drift past.','ព្រះអាទិត្យលិចនៅមេគង្គ ថ្ងៃលិចស្អាតបំផុតលើមេគង្គនៅកម្ពុជា អង្គុយនៅកាហ្វេតាមទន្លេក្រចេះ និងមើលមេឃភ្លឺខៀវលើទន្លេធំ ខណៈទូកនេសាទកំបុងឆ្លងកាត់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/Mekong River Sunset Kratie.webp','images/Mekong River Sunset Kratie.webp',NULL,NULL,'Daily evenings','Free','1',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,1,'relax'),
(123,25,6,'Koh Sdach Island','កោះស្ដេច','A remote island kingdom off the Koh Kong coast with colorful coral reefs great snorkeling simple bungalows and authentic fishing village life far from the crowds.','កោះស្ដេច រាជធានីកោះឆ្ងាយ ជ្រោះកូរ៉ាល់ពណ៌ ស្គឺបស្អាត ផ្ទះសំណាក់សាមញ្ញ និងជីវិតភូមិនេសាទពិតប្រាកដឆ្ងាយពីអ្នកទេសចរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🤿','images/Koh Sdach Island.jpg','images/Koh Sdach Island.jpg',NULL,NULL,'Day trips & overnight','From $15',NULL,NULL,NULL,NULL,'Easy',0,1,6,'2026-03-21 13:49:19','near',1.00,5.00,2.0,1,0,0,'beach'),
(124,8,2,'Sen Monorom Pine Forests','ព្រៃស្រល់','Rolling green hills covered in rare Cambodian pine forests  a magical misty landscape unique to Mondulkiri. Walk through the forest breathe cool highland air and enjoy views.','ព្រៃស្រល់ ត្បូងស្មៅអស្ចារ្យបូកព្រៃស្រល់ខ្មែរពិសេស ទេសភាពពពកចម្រុះដ៏អស្ចារ្យ ដើរតាមព្រៃ ដកដង្ហើមខ្យល់ត្រជាក់បែបព្រៃភ្នំ និងរីករាយជាមួយទិដ្ឋភាព។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌲','images/Sen Monorom Pine Forests.jpg','images/Sen Monorom Pine Forests.jpg',NULL,NULL,'Always open','Free','3',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,0,'nature'),
(125,8,4,'Dohkrormom Mountain Viewpoint','ភ្នំដោះក្រំមុំ','The highest viewpoint in Mondulkiri  climb to the summit for sweeping panoramas of pinecovered hills waterfalls and the wild eastern landscape stretching to Vietnam.','ភ្នំដោះក្រំមុំ ចំណុចមើលខ្ពស់បំផុតក្នុងមណ្ឌលគីរី ឡើងទៅកំពូលដើម្បីទិដ្ឋភាពទូលំទូលាយនៃត្បូងស្មៅ ទឹកជ្រោះ និងទេសភាពព្រៃខាងកើតរហូតទៅវៀតណាម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏔️','images/Dohkrormom Mountain Viewpoint.webp','images/Dohkrormom Mountain Viewpoint.webp',NULL,NULL,'Always open','Free','3',NULL,NULL,NULL,'Moderate',0,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,0,'mountain'),
(126,9,2,'Cha Ong Waterfall','ទឹកជ្រោះចាអូង','A stunning jungle waterfall tumbling into a cool natural pool  hike through Ratanakiri forest to swim in crystal clear water surrounded by butterflies and birdsong.','ទឹកជ្រោះចាអូង ទឹកជ្រោះព្រៃស្រស់ស្អាតធ្លាក់ចូលអាងធម្មជាតិត្រជាក់ ដើរតាមព្រៃរតនគិរី ហែលទឹកច្បាស់ ព័ទ្ធដោយមេអំបៅ និងសូរិយាបក្សី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Cha Ong Waterfall.jpg','images/Cha Ong Waterfall.jpg',NULL,NULL,'Daily 7am-5pm','$1','3',NULL,NULL,NULL,'Easy',1,1,3,'2026-03-21 13:49:19','near',1.00,5.00,2.0,1,1,0,'nature'),
(127,9,1,'Ethnic Minority Villages Ratanakiri','ភូមិជនជាតិដើមភាគតិច រតនគិរី','Visit traditional Bunong Jarai and Tampuan indigenous villages  experience ancient animist rituals carved wooden grave houses traditional weaving and rice wine ceremonies.','ភូមិជនជាតិដើមភាគតិច រតនគិរី ទស្សនាភូមិប៊ូណុង ចារ៉ៃ និងប្រពៃណីតំបូង បទពិសោធន៍ពិធីអាណិមីសបុរាណ ផ្ទះស្លាបឈើ ប្រពៃណី និងពិធីស្រាអង្ករ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏡','images/Ethnic Minority Villages Ratanakiri.jpg','images/Ethnic Minority Villages Ratanakiri.jpg',NULL,NULL,'Daily','Free guided','4',NULL,NULL,NULL,'Easy',1,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'culture'),
(128,19,2,'Sopheakmit Waterfall','ទឹកជ្រោះសោភ័ណ្ឌមិត','Dramatic Mekong rapids and waterfalls near the Laos border  boat through fastflowing channels spot rare river dolphins and experience the raw power of the upper Mekong.','ទឹកជ្រោះសោភ័ណ្ឌមិត ទឹកជ្រោះមេគង្គជិតព្រំដែនឡាវ ជិះទូកតាមបណ្តោយទន្លេរ មើលដូហ្វីនទឹកកម្រ និងទទួលបទពិសោធន៍អំណាចធម្មជាតិ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌊','images/Sopheakmit Waterfall.jpg','images/Sopheakmit Waterfall.jpg',NULL,NULL,'Daily 6am-5pm','$3','3',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-21 13:49:19','near',3.00,5.00,2.0,1,1,0,'nature'),
(132,18,2,'Kulen Promtep Wildlife Sanctuary','សត្វព្រៃគូលែន ព្រមទិព','One of Cambodia largest protected wilderness areas  a remote and wild landscape of dry forest wetlands and grasslands home to giant ibis banteng and wild elephants.','សត្វព្រៃគូលែន ព្រមទិព ដែនព្រៃធំដ៏មានការពារ ព្រៃស្ងួត ព្រៃសើម និងវាលស្មៅ រស់នៅដោយសត្វទាប បន្ទេង និងដំរីព្រៃ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦅','images/Kulen Promtep Wildlife Sanctuary.jpg','images/Kulen Promtep Wildlife Sanctuary.jpg',NULL,NULL,'Guided tours only','From $25','6',NULL,NULL,NULL,'Challenging',0,1,3,'2026-03-21 13:49:19','near',2.00,5.00,2.0,0,1,0,'nature'),
(133,12,1,'Kampong Cham French Colonial Quarter','ក្រុងបារាំង','Beautifully preserved Frenchera buildings along the Mekong  a relaxed riverside town with colonial villas oldstyle markets and the famous seasonal bamboo bridge.','ក្រុងបារាំង អគារបារាំងរចនាបទស្អាតតាមមេគង្គ ក្រុងមាត់ទន្លេស្ងប់ស្ងាត់ មានវីឡាបារាំង ផ្សារបែបចាស់ និងស្ពានឬស្សី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏛️','images/Kampong Cham French Colonial Quarter.jpg','images/Kampong Cham French Colonial Quarter.jpg',NULL,NULL,'Always open','Free','2',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'culture'),
(134,12,3,'Mekong Riverside Kampong Cham','មាត់ទន្លេមេគង់','A peaceful treelined riverside promenade in Kampong Cham  perfect for sunset walks watching river life and enjoying fresh fruit shakes at riverside cafes.','មាត់ទន្លេមេគង់ ផ្លូវដើរតាមមាត់ទន្លេរួមជាមួយដើមឈើស្ងប់ស្ងាត់នៅកំពង់ចាម ល្អសម្រាប់ដើរពេលថ្ងៃលិច មើលជីវិតសត្វទន្លេ និងផឹកកាហ្វេផ្លែឈើថ្មី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌅','images/Mekong Riverside Kampong Cham.jpg','images/Mekong Riverside Kampong Cham.jpg',NULL,NULL,'Always open','Free','1',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,1,'relax'),
(135,13,8,'Phnom Santuk Temple','ប្រាសាទភ្នំសន្តុក','A sacred hilltop covered with Buddhist shrines reclining Buddhas carved into rock faces and shady trees  a beloved pilgrimage site with beautiful views over Kampong Thom.','ប្រាសាទភ្នំសន្តុក ភ្នំបូសាស្ដានៅលើកំពូល មានស្ករាបុទ្ធ ព្រះបុទ្ធសម្បទាដាក់លើថ្ម និងដើមឈើស្រជ់ស្រក់ ទេសចរជាទីស្រលាញ់នៃការផ្សងព្រេងនឹងទិដ្ឋភាពស្អាតលើកំពង់ធំ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🙏','images/Phnom Santuk Temple.webp','images/Phnom Santuk Temple.webp',NULL,NULL,'Daily 6am-6pm','Free','2',NULL,NULL,NULL,'Moderate',1,1,2,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'religious'),
(146,23,2,'Ang Trapeang Thmor Bird Sanctuary','ឧទ្យានសត្វបក្សីអាងត្រពាំងថ្មរ','A Ramsarprotected wetland sanctuary  the only known breeding ground of the critically endangered sarus crane in Southeast Asia plus hundreds of other water birds.','ឧទ្យានសត្វបក្សីអាងត្រពាំងថ្មរ ដែនស្នាក់នៅទឹកសាប ការពារ ដោយ Ramsar ជាតំបន់បង្កប់សត្វឈុត Sarus Crane តែមួយនៅអាស៊ីអាគ្នេយ៍ រួមទាំងបក្សីទឹករាប់រយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦩','images/Ang Trapeang Thmor Bird Sanctuary.webp','images/Ang Trapeang Thmor Bird Sanctuary.webp',NULL,NULL,'Nov-May best','$5','3',NULL,NULL,NULL,'Easy',1,1,3,'2026-03-21 13:49:19','near',5.00,5.00,2.0,1,1,0,'nature'),
(147,17,1,'Ta Moan Temple Complex','ប្រាសាទ Ta Moan','Ancient Angkorera temples straddling the Thai border  three temple groups in remote jungle accessed by rough roads offering an authentic offthebeatenpath adventure.','ប្រាសាទ តាម៉ាន់ ប្រាសាទអង្គរបុរាណលើព្រំដែនថៃ ក្រុមប្រាសាទ ៣ ក្នុងព្រៃឆ្ងាយ ចូលតាមផ្លូវ បទពិសោធន៍ដើរតាមផ្លូវឯកសិទ្ធិ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏯','images/Ta Moan Temple Complex.webp','images/Ta Moan Temple Complex.webp',NULL,NULL,'Daily 7am-5pm','$3','4',NULL,NULL,NULL,'Moderate',0,1,3,'2026-03-21 13:49:19','near',3.00,5.00,2.0,1,0,0,'culture'),
(148,21,8,'Ba Phnom Sacred Mountain','ភ្នំបាភ្នំ','One of the most sacred pilgrimage sites in Cambodia  an ancient hilltop temple with deep spiritual significance stunning rice field views and a lively festival each year.','ភ្នំបាភ្នំ គេហៅថាតំបន់បរិញ្ញាណបូជា មានប្រាសាទលើភ្នំបុរាណ មានអត្ថន័យផ្លូវចិត្តខ្លាំង ទិដ្ឋភាពវាលស្រែស្រស់ស្អាត និងពិធីបុណ្យប្រចាំឆ្នាំយ៉ាងរីករាយ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🙏','images/Ba Phnom Sacred Mountain.jpg','images/Ba Phnom Sacred Mountain.jpg',NULL,NULL,'Daily 6am-6pm','Free','2',NULL,NULL,NULL,'Easy',1,1,1,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'religious'),
(149,21,3,'Svay Rieng Rice Fields','វាលស្រែ','Endless golden rice fields stretching to the horizon  cycle through villages meet farmers and experience the timeless rhythm of rural Cambodian life near the Vietnamese border.','វាលស្រែ វាលស្រឡាយពណ៌មាសពោរពេញលែងដល់ horizonte ជិះកង់តាមភូមិ ជួបកសិករ និងទទួលបទពិសោធន៍ជីវិតភូមិខ្មែរព្រំដែនវៀតណាម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌾','images/Svay Rieng Rice Fields.webp','images/Svay Rieng Rice Fields.webp',NULL,NULL,'Always open','Free','3',NULL,NULL,NULL,'Easy',0,1,2,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,1,1,'relax'),
(150,20,8,'Wat Phnom Prasat Ancient Ruins','ភូមិប្រាសាទ','Ancient preAngkorian temple ruins on a small hill in the Prey Veng countryside  a rarely visited archaeological site with carved sandstone blocks and local pilgrims.','ភូមិប្រាសាទ ប្រាសាទមុនអង្គរដែលស្ថិតលើភ្នំតូចនៅជនបទព្រៃវែង មានការទេសចរតិច មានថ្មសំណាញ់ និងអ្នកធ្វើដំណើរទស្សនា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏯','images/Wat Phnom Prasat Ancient Ruins.webp','images/Wat Phnom Prasat Ancient Ruins.webp',NULL,NULL,'Daily 6am-6pm','Free','2',NULL,NULL,NULL,'Easy',0,1,1,'2026-03-21 13:49:19','city',0.00,5.00,2.0,1,0,0,'religious'),
(152,22,2,'O Tavao Waterfall Pailin','ទឹកជ្រោះអូតាវ៉ៅ','A beautiful jungle waterfall near the Thai border  swim in the natural pool picnic on the rocks and enjoy the cool forest atmosphere away from the heat.','ទឹកជ្រោះអូតាវ៉ៅ ទឹកជ្រោះព្រៃស្រស់ស្អាតជិតព្រំដែនថៃ(សៀម) ហែលក្នុងអាងធម្មជាតិ picnic លើថ្ម និងរីករាយអាកាសត្រជាក់ក្នុងព្រៃ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/O Tavao Waterfall Pailin.webp','images/O Tavao Waterfall Pailin.webp',NULL,NULL,'Daily 7am-5pm','$1','2',NULL,NULL,NULL,'Easy',0,1,3,'2026-03-21 13:49:19','near',1.00,5.00,2.0,1,1,0,'nature'),
(180,5,5,'Arcadia Waterpark Kampot River','ឧទ្យានទឹក Arcadia','Cambodia most famous riverside adventure park  giant water slide blob launcher rope swing 6m jumping platform kayaks and inner tubes on the Kampot River. Pure adrenaline fun.','ឧទ្យានទឹក Arcadia ឧទ្យានជម្រើសអស្ចារ្យល្បីល្បាញនៅកម្ពុជាដោយទន្លេ មានទឹកជ្រោះធំ បាញ់ទឹក លេងខ្សែ វិញ្ញាសាកែលី ៦ម៉ែត្រ កាយ៉ាក់ និងបណ្ណូលក្នុងទឹក។ ភាពសប្បាយបែបអារម្មណ៍រំភើបពេញលេញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Arcadia Waterpark Kampot River.jpg','images/Arcadia Waterpark Kampot River.jpg',NULL,NULL,'Daily 9am-6pm','$8','4',NULL,NULL,NULL,'Easy',1,1,9,'2026-03-21 13:56:59','near',NULL,5.00,2.0,1,0,0,'fun'),
(181,5,5,'Rock Climbing Kampot Limestone','ការឡើងភ្នំតាមថ្ម កំពត','Kampot is Southeast Asia emerging rock climbing destination  dramatic limestone cliffs with routes for all levels stunning views and professional guides from Climbodia.','ការឡើងភ្នំតាមថ្ម កំពត កំពតជាគោលដៅឡើងភ្នំថ្មីនៅអាស៊ីអាគ្នេយ៍ ជ័រថ្មលីមស្តូនស្រស់ស្អាត មានផ្លូវសម្រាប់កម្រិតទាំងអស់ ទិដ្ឋភាពអស្ចារ្យ និងមគ្គុទេសក៍អ្នកជំនាញពី Climbodia។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🧗','images/Rock Climbing Kampot Limestone.jpeg','images/Rock Climbing Kampot Limestone.jpeg',NULL,NULL,'Daily 7am-5pm','From $25','4',NULL,NULL,NULL,'Moderate',0,1,10,'2026-03-21 13:56:59','near',2.00,5.00,2.0,1,0,0,'fun'),
(182,5,5,'Paddleboarding on Kampot River','ការជិះទូកកងទឹកលើទន្លេខំបុត្រ','Standup paddleboard down the calm Kampot River at golden hour  glide past mangroves pepper farms and stilted fishing villages as the sun turns everything orange.','ការជិះទូកកងទឹកលើទន្លេខំបុត្រ ជិះ paddleboard ឈរ លើទន្លេកំពតស្ងប់ស្ងាត់ពេលម៉ោងព្រះអាទិត្យលិច រត់កាត់ព្រៃទឹក ចំការម្រេច និងភូមិមាត់ទឹកទន្លេលើដំបូលខ្នងពេលថ្ងៃបំភ្លឺទាំងអ្វីៗជាពណ៌ទឹកក្រហម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏄','images/Paddleboarding on Kampot River.jpg','images/Paddleboarding on Kampot River.jpg',NULL,NULL,'Daily 6am-6pm','From $10','2',NULL,NULL,NULL,'Easy',0,1,11,'2026-03-21 13:56:59','near',1.00,5.00,2.0,1,0,0,'fun'),
(183,5,5,'Buffalo Cart Countryside Tour Kampot','ដំណើរជិះរទេះក្របី','Ride a traditional wooden buffalo cart through Kampot countryside  visit pepper plantations salt fields and village temples at a beautifully slow pace with a local guide.','ដំណើរជិះរទេះក្របី ជិះរទេះក្របីឈើបុរាណតាមជនបទកំពត ទស្សនាចំការម្រេច វាលអំបិល និងវត្តភូមិ ជាមួយមគ្គុទេសក៍ក្នុងស្រុក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐃','images/Buffalo Cart Countryside Tour Kampot.webp','images/Buffalo Cart Countryside Tour Kampot.webp',NULL,NULL,'Daily 8am-5pm','From $20','3',NULL,NULL,NULL,'Easy',0,1,12,'2026-03-21 13:56:59','near',2.00,5.00,2.0,1,0,0,'fun'),
(184,5,3,'Kampot Rooftop Sunset Bars','ញុំអាហារមើលថ្ងៃលិចដំបូល','The best sunset cocktails in Cambodia  Kampot riverside rooftop bars with views over the river pepper fields and Bokor Mountain glowing in the evening light.','ញុំអាហារមើលថ្ងៃលិចដំបូល អាហារប្រភេទ cocktail ថ្ងៃលិចល្អបំផុតនៅកម្ពុជា បារដំបូលតាមទន្លេកំពត មើលទន្លេ វាលម្រេច និងភ្នំបូករបំភ្លឺពេលល្ងាច។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🍹','images/Kampot Rooftop Sunset Bars.jpg','images/Kampot Rooftop Sunset Bars.jpg',NULL,NULL,'Daily 4pm-midnight','Free','2',NULL,NULL,NULL,'Easy',0,1,13,'2026-03-21 13:56:59','city',0.00,5.00,2.0,1,1,1,'relax'),
(185,5,2,'Popokvil Waterfall Bokor','ទឹកជ្រោះពពកវិល ភ្នំបូករ','A stunning doubletiered waterfall high in Bokor National Park  swim in the cool mountain pools surrounded by mist and jungle. Most beautiful during and after wet season.','ទឹកជ្រោះពពកវិល ភ្នំបូករ ទឹកជ្រោះពីរ ស្ថិតខ្ពស់នៅឧទ្យានជាតិភ្នំបូករ ហែលក្នុងទឹកត្រជាក់ព័ទ្ធដោយពពក និងព្រៃ។ ស្អាតបំផុតក្នុងរដូវភ្លៀង និងក្រោយភ្លៀង។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Popokvil Waterfall Bokor.jpg','images/Popokvil Waterfall Bokor.jpg',NULL,NULL,'Daily 6am-5pm','Park fee $5','3',NULL,NULL,NULL,'Easy',0,1,14,'2026-03-21 13:56:59','near',5.00,5.00,2.0,1,1,0,'nature'),
(186,6,5,'Kep Pepper Farm Cycling Tour','ជិះកង់ចំការម្រេចកែប','Cycle through Kep and Kampot pepper plantations  taste fresh green red and black pepper straight from the vine and learn the history of Cambodia worldfamous Kampot pepper.','ជិះកង់ចំការម្រេចកែប ជិះកង់តាមចំការម្រេចកែប និងកំពត សាករសជាតិម្រេចបៃតង ក្រហម និងខ្មៅ ពីដើម និងសិក្សាប្រវត្តិម្រេចកំពតល្បីល្បាញទូទាំងពិភពលោក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌶️','images/Kep Pepper Farm Cycling Tour.jpg','images/Kep Pepper Farm Cycling Tour.jpg',NULL,NULL,'Daily 7am-5pm','From $15','3',NULL,NULL,NULL,'Easy',1,1,6,'2026-03-21 13:56:59','near',1.00,5.00,2.0,1,0,0,'fun'),
(187,6,7,'Kep Seafood Cooking Class','ថ្នាក់ធ្វើម្ហូបសមុទ្រកែប','Learn to cook authentic Khmer seafood dishes using fresh Kep crab and Kampot pepper  a handson cooking class with a local chef followed by eating your own creation.','ថ្នាក់ធ្វើម្ហូបសមុទ្រកែប រៀនចម្អិនម្ហូបសមុទ្រខ្មែរពិតប្រាកដដោយក្តាមកែបថ្មី និងម្រេចកំពត ថ្នាក់ចម្អិនដោយមានចុងភៅក្នុងស្រុក ហើយបរិច្ឆេទម្ហូបដែលអ្នកធ្វើ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'👨‍🍳','images/Kep Seafood Cooking Class.webp','images/Kep Seafood Cooking Class.webp',NULL,NULL,'Daily 9am-1pm','From $25','3',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 13:56:59','near',2.00,5.00,2.0,1,0,1,'food'),
(189,25,5,'Botum Sakor National Park','ឧទ្យានជាតិ បូតុមសាកួ','A vast coastal national park  boat through mangroves hike to pristine beaches spot rare sun bears and leopards and camp under stars on deserted island beaches.','ឧទ្យានជាតិ បូតុមសាកួ ឧទ្យានជាតិឆ្នេរធំ ជិះទូកតាមម៉ង់ក្រោវ ដើរទៅឆ្នេរស្អាត មើលសមុទ្រដ៏កម្រ និងខ្លាឃ្មុំ សម្រាកក្រោមផ្កាយលើឆ្នេរក្នុងកោះ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌲','images/Botum Sakor National Park.png','images/Botum Sakor National Park.png',NULL,NULL,'Guided tours only','From $30',NULL,NULL,NULL,NULL,'Moderate',0,1,8,'2026-03-21 13:56:59','near',3.00,5.00,2.0,1,0,0,'fun'),
(194,8,7,'Sen Monorom Coffee and Avocado Farm','កសិដ្ឋានកាហ្វេ Sen Monorom','Mondulkiri is Cambodia coffee and avocado capital  visit highland farms growing specialty coffee and avocados enjoy fresh farmtocup brews with mountain views.','កសិដ្ឋានកាហ្វេ Sen Monorom មណ្ឌលគីរីជាទីក្រុងកាហ្វេ និងអាវូខាដូខ្មែរដ៏ល្បី ទស្សនាកសិដ្ឋានភ្នំដែលដាំកាហ្វេឯកទេស និងអាវូខាដូ រីករាយកាហ្វេថ្មីពីកសិដ្ឋានជាមួយទិដ្ឋភាពភ្នំ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'☕','images/Sen Monorom Coffee and Avocado Farm.webp','images/Sen Monorom Coffee and Avocado Farm.webp',NULL,NULL,'Daily 7am-5pm','Free tour','2',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 13:56:59','city',0.00,5.00,2.0,1,0,1,'food'),
(195,9,5,'Kachanh Waterfall Ratanakiri','ទឹកជ្រោះ កាចាញ់','A beautiful jungle waterfall with resident elephants  hike through Ratanakiri forest to this magical swimming spot where wild elephants are sometimes spotted bathing nearby.','ទឹកជ្រោះ កាចាញ់ ទឹកជ្រោះព្រៃស្រស់ស្អាត មានដំរីរស់នៅ ដើរតាមព្រៃរតនគិរី ទៅកន្លែងហែលទឹកអស្ចារ្យនេះដែលខ្លាឃ្មុំព្រៃខ្លះៗហែលទឹកនៅជិត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🐘','images/Kachanh Waterfall Ratanakiri.png','images/Kachanh Waterfall Ratanakiri.png',NULL,NULL,'Daily 7am-5pm','$2','4',NULL,NULL,NULL,'Moderate',1,1,5,'2026-03-21 13:56:59','near',2.00,5.00,2.0,1,0,0,'fun'),
(196,9,5,'Lumphat Wildlife Sanctuary Trek','ការពារសត្វព្រៃលំផាត់','A remote wildlife sanctuary with guided ranger treks  track elephants spot gibbons and camp in pristine jungle far from any roads in one of Cambodia last truly wild places.','ការពារសត្វព្រៃលំផាត់ ដែនសត្វព្រៃឆ្ងាយ មានដំណើរដឹកនាំដោយអ្នករក្សាសត្វ តាមដំរី មើលសត្វ និងស្នាក់នៅព្រៃស្អាតឆ្ងាយពីផ្លូវមួយកន្លែងក្នុងព្រៃធម្មជាតិចុងក្រោយនៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌲','images/Lumphat Wildlife Sanctuary Trek.jpg','images/Lumphat Wildlife Sanctuary Trek.jpg',NULL,NULL,'Guided only','From $40',NULL,NULL,NULL,NULL,'Challenging',0,1,6,'2026-03-21 13:56:59','near',NULL,5.00,2.0,0,0,0,'fun'),
(199,18,5,'Prasat Thom Koh Ker Pyramid Climb','ការឡើងជើងពិរាមីដប្រាសាទធំកោះគេរ','Climb the steep steps of the 7storey Prasat Thom pyramid for panoramic views of the jungle canopy stretching to the horizon  one of the most thrilling temple experiences in Cambodia.','ការឡើងជើង ពីរ៉ាមីត ប្រាសាទធំកោះគេរ ជិះជើងជាន់ខ្ពស់ ៧ជាន់នៃពីរ៉ាមីត ទិដ្ឋភាពព្រៃឆ្ងាយដល់អាកាស បទពិសោធន៍ប្រាសាទដ៏អស្ចារ្យនៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🔺','images/Prasat Thom Koh Ker Pyramid Climb.jpg','images/Prasat Thom Koh Ker Pyramid Climb.jpg',NULL,NULL,'Daily 7:30am-5pm','$10','3',NULL,NULL,NULL,'Moderate',1,1,4,'2026-03-21 13:56:59','near',1.00,5.00,2.0,1,0,0,'fun'),
(203,13,5,'Prey Pros Community Fishing Lake','បឹងត្រី ព្រៃប្រុស','A beautiful communitymanaged lake where you can fish with locals enjoy a riverside picnic and experience authentic Cambodian rural life far from the tourist trail.','បឹងត្រី ព្រៃប្រុស បឹងស្អាតដែលគ្រប់គ្រងដោយសហគមន៍ អាចចាប់ត្រីជាមួយអ្នកក្នុងស្រុក ដើរតាមមាត់ទន្លេ និងបទពិសោធន៍ជីវិតជនបទ ពេញលេញឆ្ងាយពីផ្លូវទេសចរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎣','images/Prey Pros Community Fishing Lake.webp','images/Prey Pros Community Fishing Lake.webp',NULL,NULL,'Always open','Free','3',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:56:59','city',0.00,5.00,2.0,1,0,0,'fun'),
(206,14,5,'Kirirom Waterfall Swimming','ទឹកជ្រោះ គីរីរម្យ','Cool waterfalls tumbling through pine forest in Kirirom National Park  swim in natural pools hike forest trails and enjoy the rare pinescented cool air unique to this highland park.','ទឹកជ្រោះ គីរីរម្យ ទឹកជ្រោះត្រជាក់ហែលតាមព្រៃស្រល់ ហែលក្នុងអាងធម្មជាតិ ដើរតាមផ្លូវព្រៃ និងរីករាយអាកាសត្រជាក់មានក្លិនស្រល់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Kirirom Waterfall Swimming.jpg','images/Kirirom Waterfall Swimming.jpg',NULL,NULL,'Daily 7am-5pm','Park $5','4',NULL,NULL,NULL,'Easy',1,1,4,'2026-03-21 13:56:59','near',5.00,5.00,2.0,1,0,0,'fun'),
(209,16,4,'Phnom Kravanh Cardamom Hike','ដើរឡើងភ្នំក្រវាញ','A guided trek deep into the Cardamom Mountains from Pursat  follow rivers through ancient jungle spot wildlife and camp at waterfalls in one of Southeast Asia last great wilderness areas.','ដើរឡើងភ្នំក្រវាញ ដំណើរដឹកនាំជាមួយមាគ៌ាចូលក្នុងភ្នំកាដាមូមពីពោធិ៍សាត់ តាមទន្លេតាមព្រៃបុរាណ មើលសត្វព្រៃ និងសម្រាកនៅទឹកជ្រោះ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌴','images/Phnom Kravanh Cardamom Hike.jpg','images/Phnom Kravanh Cardamom Hike.jpg',NULL,NULL,'Guided only','From $45',NULL,NULL,NULL,NULL,'Challenging',0,1,5,'2026-03-21 13:56:59','near',NULL,5.00,2.0,0,1,0,'mountain'),
(212,17,1,'Anlong Veng Pol Pot Grave','ប្រវត្តិ Pol Pot','The final resting place of Pol Pot  a small matteroffact grave in the jungle. Visit the houses of former Khmer Rouge leaders and learn about the final chapter of this dark regime.','ប្រវត្តិ ប៉ុល​ ពត អាសយដ្ឋានចុងក្រោយរបស់ប៉ុលពត ប្រាង្សតូចនៅក្នុងព្រៃ មើលផ្ទះមេដឹកនាំខ្មែរក្រហមចាស់ និងសិក្សាអំពីចុងក្រោយនៃរបបនេះ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕯️','images/Anlong Veng Pol Pot Grave.jpg','images/Anlong Veng Pol Pot Grave.jpg',NULL,NULL,'Daily 7am-5pm','$5','3',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:56:59','near',5.00,5.00,2.0,1,0,0,'culture'),
(215,11,5,'Koh Dach Silk Weaving Village','ភូមិតំបាញក្រណាត់សូត្រកោះដាច់','Watch silk weavers at work on traditional wooden looms on this peaceful Mekong island just 15km from Phnom Penh  buy beautiful handwoven scarves sarongs and wall hangings.','ភូមិតំបាញក្រណាត់សូត្រកោះដាច់ មើលអ្នកចងសូត្រធ្វើការលើចង្ក្រានឈើប្រពៃណី នៅកោះស្ងប់ស្ងាត់លើមេគង្គ ១៥គមពីភ្នំពេញ ទិញសូត្រធ្វើដៃ សាឡុង និងការតុបតែងជញ្ជាំងដ៏ស្រស់ស្អាត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🧵','images/Koh Dach Silk Weaving Village.jpg','images/Koh Dach Silk Weaving Village.jpg',NULL,NULL,'Daily 7am-5pm','Free ferry','3',NULL,NULL,NULL,'Easy',1,1,5,'2026-03-21 13:56:59','city',0.00,5.00,2.0,1,0,0,'fun'),
(218,10,3,'Takeo Lotus Blossom Lake','បឹងផ្កាឈូក Takeo','An enormous lotuscovered lake surrounding Takeo town  hire a small boat and drift through thousands of pink lotus flowers at dawn with fishermen casting nets in the mist.','បឹងផ្កាឈូក តាកែវ បឹងធំដែលព័ទ្ធដោយផ្កាឈូកនៅជុំវិញទីក្រុងតាកែវ ជួលទូកតូចជិះតាមផ្កាឈូកពណ៌ផ្កាឈូករាប់ពាន់នៅពេលព្រឹក មើលអ្នកនេសាទ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌸','images/Takeo Lotus Blossom Lake.webp','images/Takeo Lotus Blossom Lake.webp',NULL,NULL,'Daily 5am-6pm','Boat from $3','2',NULL,NULL,NULL,'Easy',0,1,6,'2026-03-21 13:56:59','near',3.00,5.00,2.0,1,1,1,'relax'),
(221,24,3,'Tboung Khmum Countryside Homestay','ការស្នាក់នៅផ្ទះជាតំបន់ជនបទត្បូងឃ្មុំ','Stay overnight with a local Cambodian family in Tboung Khmum  cook traditional meals together learn to weave cycle through rubber plantations and experience real rural life.','ការស្នាក់នៅផ្ទះជាតំបន់ជនបទត្បូងឃ្មុំ ស្នាក់នៅជាមួយគ្រួសារខ្មែរមូលដ្ឋាន ធ្វើម្ហូបបុរាណ រៀនអូសខ្សែ ជិះកង់តាមចំការកៅស៊ូ និងទទួលបទពិសោធន៍ជីវិតអ្នកភូមិពិតប្រាកដ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏡','images/Tboung Khmum Countryside Homestay.jpg','images/Tboung Khmum Countryside Homestay.jpg',NULL,NULL,'Overnight','From $15',NULL,NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 13:56:59','near',1.00,5.00,2.0,1,1,1,'relax'),
(222,7,5,'Koh Trong Cycling and Homestay','ជិះកង់ក្នុងកោះត្រង','Cycle the entire circumference of this peaceful Mekong island in 2 hours  rice paddies Cham Muslim mosques pomelo orchards and homestays with local families who fish the great river.','ជិះកង់ក្នុងកោះត្រង ជិះកង់ជុំវិញកោះមេគង្គស្ងប់ស្ងាត់នេះក្នុងរយៈពេល ២ម៉ោង វាលស្រូវ ប្រាសាទមូស្លីមចាម ចំការសំបូរ និងស្នាក់នៅជាមួយគ្រួសារក្នុងស្រុកដែលចាំបាច់នេសាទត្រីក្នុងទន្លេធំ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚴','images/Koh Trong Cycling and Homestay.jpg','images/Koh Trong Cycling and Homestay.jpg',NULL,NULL,'Always open (dry season)','Free ferry $0.50','3',NULL,NULL,NULL,'Easy',1,1,5,'2026-03-21 13:56:59','city',0.00,5.00,2.0,1,0,0,'fun'),
(237,5,5,'La Plantation Kampot Pepper Farm','ចំការម្រេច La Plantation','One of the world most famous pepper farms  guided tours through lush green vines taste all four varieties of Kampot pepper fresh off the plant and buy directly from the source.','ចំការម្រេច La Plantation ចំការម្រេចល្បីល្បាញបំផុតក្នុងពិភពលោក ទស្សនាដោយមគ្គុទេសក៍តាមឆ្នូតបៃតង សាករសជាតិម្រេចកំពតបួនប្រភេទ ពីដើម និងទិញដោយផ្ទាល់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌶️','images/La Plantation Kampot Pepper Farm.avif','images/La Plantation Kampot Pepper Farm.avif',NULL,NULL,'Daily 8am-5pm','Free tour','2',NULL,NULL,NULL,'Easy',1,1,15,'2026-03-21 14:02:39','city',0.00,5.00,2.0,1,0,0,'fun'),
(238,5,3,'Banteay Srey Women Spa Kampot','ស្ប៉ាបន្ទាយស្រីនៅកំពត','A social enterprise spa run by and employing Cambodian women  traditional Khmer massage herbal scrubs and wellness treatments in a beautiful garden setting by the river.','ស្ប៉ាបន្ទាយស្រីនៅកំពត ស្ប៉ាសហគ្រាសសង្គម ដំណើរការ និងជ្រើសរើសស្រ្តីខ្មែរ មានម៉ាស្សាខ្មែរបុរាណ ប្រូសជែលស្មៅសរីរាង្គ និងការថែរក្សាសុខភាពក្នុងសួនស្អាតជិតទន្លេ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💆','images/Banteay Srey Women Spa Kampot.webp','images/Banteay Srey Women Spa Kampot.webp',NULL,NULL,'Daily 9am-9pm','From $8','2',NULL,NULL,NULL,'Easy',0,1,16,'2026-03-21 14:02:39','near',NULL,5.00,2.0,1,1,1,'relax'),
(239,5,5,'Kampot Night Market','ផ្សាររាត្រីកំពត','A lively riverside night market with local street food handmade crafts live music and cold beers  the best place to meet locals and other travelers in a relaxed riverside setting.','ផ្សាររាត្រីកំពត ផ្សាររាត្រីតាមទន្លេចលាចលា មានម្ហូបតាមដងផ្លូវ សិប្បកម្មដោយដៃ តន្រ្តីផ្សាយបន្តផ្ទាល់ និងស្រាក្ដៅៗ ជាកន្លែងល្អបំផុតសម្រាប់ជួបជនជាតិ និងអ្នកទេសចរ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌙','images/Kampot Night Market.jpg','images/Kampot Night Market.jpg',NULL,NULL,'Daily 5pm-11pm','Free','2',NULL,NULL,NULL,'Easy',0,1,17,'2026-03-21 14:02:39','city',0.00,5.00,2.0,1,0,0,'fun'),
(243,8,5,'Waterfall Quad Biking Mondulkiri','ជិះម៉ូតូ ATV មើលទឹកជ្រោះ','Ride powerful ATVs through Mondulkiri highlands  blast through pine forests Bunong villages and river crossings to reach hidden waterfalls deep in the eastern highlands.','ជិះម៉ូតូ ATV មើលទឹកជ្រោះ ជិះម៉ូតូកង់បួនកម្លាំងខ្លាំងតាមភ្នំមណ្ឌលគីរី ឆ្លងតាមព្រៃស្រល់ ភូមិប៊ូណុង និងឆ្លងទន្លេដើម្បីទៅទឹកជ្រោះលាក់នៅក្នុងភ្នំខាងកើត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🏍️','images/Waterfall Quad Biking Mondulkiri.jpg','images/Waterfall Quad Biking Mondulkiri.jpg',NULL,NULL,'Daily 7am-5pm','From $45','4',NULL,NULL,NULL,'Moderate',0,1,8,'2026-03-21 14:02:39','near',NULL,5.00,2.0,1,0,0,'fun'),
(244,8,2,'Monorom Waterfall Sen Monorom','ទឹកជ្រោះ Monorom','A series of beautiful cascading waterfalls just outside Sen Monorom town  swim in natural rock pools picnic in the mist and spot exotic birds in the surrounding pine forest.','ទឹកជ្រោះ Monorom ស៊េរីទឹកជ្រោះស្រស់ស្អាតនៅក្រៅទីក្រុងសែនមនោរម្យ ហែលទឹកក្នុងអាងក្រចកធម្មជាតិ មើលពពក និងមើលសត្វបក្សីអស្ចារ្យនៅព្រៃស្រល់ជុំវិញ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Monorom Waterfall Sen Monorom.jpg','images/Monorom Waterfall Sen Monorom.jpg',NULL,NULL,'Daily 7am-5pm','$1','2',NULL,NULL,NULL,'Easy',0,1,9,'2026-03-21 14:02:39','near',1.00,5.00,2.0,1,1,0,'nature'),
(246,9,2,'Yeak Laom Sacred Forest Walk','ដើរព្រៃ យក្យឡោម','A circular walking trail through ancient sacred forest around the volcanic crater lake  the Bunong people consider this forest alive with spirits. Listen look and feel the atmosphere.','ដើរព្រៃ យក្យឡោម ផ្លូវដើរឈរជុំវិញព្រៃបុរាណនៅជុំវិញបឹងភ្នំ ជនប៊ូណុងជឿថាព្រៃនេះរស់នៅដោយវិញ្ញាណ ចាំស្តាប់ មើល និងអារម្មណ៍នៅក្នុងបរិយាកាស។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🌿','images/Yeak Laom Sacred Forest Walk.jpg','images/Yeak Laom Sacred Forest Walk.jpg',NULL,NULL,'Daily 7am-6pm','$5 lake entry','1',NULL,NULL,NULL,'Easy',0,1,9,'2026-03-21 14:02:39','near',5.00,5.00,2.0,1,1,0,'nature'),
(247,12,5,'Mekong Kayaking Kampong Cham','ជិះទូកនៅមេគង្គ ខេត្តកំពង់ចាម','Kayak on the Mekong around Kampong Cham  paddle to river islands past fishing communities and through calm channels at sunset when the water turns gold and red.','ជិះទូកនៅមេគង្គ ខេត្តកំពង់ចាម ជិះកាយ៉ាក់លើមេគង្គជុំវិញកំពង់ចាម ឆ្លងកោះទន្លេ ភូមិនេសាទ និងសូម្បីតាមស្ទឹងស្ងប់ស្ងាត់ពេលថ្ងៃលិច ទឹកប្ដូរពណ៌មាស និងក្រហម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚣','images/Mekong Kayaking Kampong Cham.jpg','images/Mekong Kayaking Kampong Cham.jpg',NULL,NULL,'Daily 6am-5pm','From $15','3',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 14:02:39','near',1.00,5.00,2.0,1,0,0,'fun'),
(248,12,7,'Kampong Cham Local Food Tour','ម្ហូបតាមតំបន់','Sample the unique food of Kampong Cham  famous for its pork sausages river fish dishes and the local specialty of banh chao (Khmer sizzling crepes) made fresh at street stalls.','ម្ហូបតាមតំបន់ សាករសជាតិម្ហូបដ៏ឯកទេសនៃកំពង់ចាម ល្បីល្បាញក្នុងការចម្អិនសាច់ជ្រូក មុខម្ហូបត្រីទន្លេ និងបាញ់ឆៅ (បាញ់ចោ) ផ្តល់ថ្មីនៅផ្សារចត្រង្គ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🍜','images/Kampong Cham Local Food Tour.jpg','images/Kampong Cham Local Food Tour.jpg',NULL,NULL,'Daily 7am-noon','Free','2',NULL,NULL,NULL,'Easy',0,1,8,'2026-03-21 14:02:39','city',0.00,5.00,2.0,1,0,1,'food'),
(249,14,5,'Kirirom Pine Forest Camping','ជំរុំព្រៃ គីរីរម្យ','Camp overnight in Kirirom pine forest  wake up to crisp mountain air morning mist birdsong and the magical experience of camping in Cambodia only pine forest high above the plains.','ជំរុំព្រៃ គីរីរម្យ ដាំសាកនៅព្រៃស្រល់គីរីរម្យ យកអាកាសត្រជាក់ភ្នំ ពពកពេលព្រឹក សម្លេងសត្វយំ និងបទពិសោធន៍អស្ចារ្យនៃការសម្រាកក្នុងព្រៃស្រល់ខ្ពស់នៅកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'⛺','images/Kirirom Pine Forest Camping.jpg','images/Kirirom Pine Forest Camping.jpg',NULL,NULL,'Camping allowed','From $5',NULL,NULL,NULL,NULL,'Easy',0,1,6,'2026-03-21 14:02:39','near',5.00,5.00,2.0,1,0,0,'fun'),
(250,16,5,'Cardamom Mountains Wildlife Night Walk','ការដើរព្រៃយប់នៅភ្នំ Cardamom','A guided night walk in the Cardamom Mountains buffer zone  spot civets slow loris owls flying squirrels and luminescent fungi with an expert local ranger. Truly magical.','ការដើរព្រៃយប់នៅភ្នំ ខាដាម៉ាម ដើរព្រៃយប់ដោយមគ្គុទេសក៍ មើលសត្វ Civet Lorises គោល សត្វហោះ និងស៊ុមភ្លឺពន្លឺជាមួយការណែនាំអ្នករក្សាព្រៃ អស្ចារ្យពិតប្រាកដ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦉','images/Cardamom Mountains Wildlife Night Walk.jpg','images/Cardamom Mountains Wildlife Night Walk.jpg',NULL,NULL,'Nightly 7pm','From $25','2',NULL,NULL,NULL,'Moderate',0,1,6,'2026-03-21 14:02:39','near',2.00,5.00,2.0,1,0,0,'fun'),
(251,11,5,'Phnom Tamao Zip Line and Wildlife Walk','ភូមិទ្រនំ Phnom Tamao','A new zipline experience through the treetops of Phnom Tamao Wildlife Rescue Center  soar above rescued animals and lush forest on zip lines then walk through the sanctuary on foot.','ភូមិទ្រនំ ភ្នំតាម៉ៅ បទពិសោធន៍ថ្មីតាមកំពូលភ្នំ ដើមឈើមជ្ឈមណ្ឌលសត្វព្រៃភ្នំតាមៅ រហិចលើសត្វដែលបានសង្គ្រោះ និងព្រៃស្រស់ បន្ទាប់មកដើរតាមមើលសត្វ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🧗','images/Phnom Tamao Zip Line and Wildlife Walk.webp','images/Phnom Tamao Zip Line and Wildlife Walk.webp',NULL,NULL,'Daily 8am-4pm','$15','3',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 14:02:39','near',1.00,5.00,2.0,1,0,0,'fun'),
(252,11,7,'Kandal Market Fresh Seafood','ផ្សារត្រីសមុទ្រស្រស់','The freshest river fish in Cambodia  Kandal province market stalls serve grilled snakehead fish river shrimp and freshwater crab dishes that Phnom Penh locals drive out specially to eat.','ផ្សារត្រីសមុទ្រស្រស់ ត្រីទន្លេស្រស់បំផុតនៅកម្ពុជា កំពូលផ្សារខេត្តកណ្ដាលផ្ដល់មុខម្ហូបត្រី បង្កងទន្លេ និងក្តាមទឹកប្រៃ ដែលអ្នកភ្នំពេញមកសម្រាប់សាករសជាតិ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🦐','images/Kandal Market Fresh Seafood.jpg','images/Kandal Market Fresh Seafood.jpg',NULL,NULL,'Daily 6am-5pm','Free','2',NULL,NULL,NULL,'Easy',0,1,8,'2026-03-21 14:02:39','city',0.00,5.00,2.0,1,0,1,'food'),
(253,10,5,'Phnom Da Kayak and Temple Tour','ទូក Phnom Da','Kayak through flooded rice fields to the dramatic Phnom Da hilltop temple  one of the most unique temple access experiences in Cambodia passing through water and lotus flowers.','ទូក ភ្នំដា ជិះកាយ៉ាក់តាមវាលអង្ករទៅប្រាសាទភ្នំដាខ្ពស់ មួយក្នុងចំណោមបទពិសោធន៍ចូលប្រាសាទដ៏ឯកទេសនៅកម្ពុជា ឆ្លងតាមទឹក និងផ្កាឈូក។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚣','images/Phnom Da Kayak and Temple Tour.jpg','images/Phnom Da Kayak and Temple Tour.jpg',NULL,NULL,'Daily tours','From $15','4',NULL,NULL,NULL,'Easy',0,1,7,'2026-03-21 14:02:39','near',1.00,5.00,2.0,1,0,0,'fun'),
(258,21,7,'Svay Rieng Local Market Food','ម្ហូបតំបន់ស្វាយរៀង','Taste Svay Rieng specialties at the local market  this border province has unique food influenced by both Khmer and Vietnamese cuisine including fresh rice paper rolls and river fish dishes.','ម្ហូបតំបន់ស្វាយរៀង សាករសជាតិម្ហូបពិសេសស្វាយរៀងនៅផ្សារធម្មតា មានេសជាតិខ្មែរនិងវៀតណាម រួមមាននំបញ្ចុក និងម្ហូបទន្លេស្រស់។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🍜','images/Svay Rieng Local Market Food.jpg','images/Svay Rieng Local Market Food.jpg',NULL,NULL,'Daily 5am-noon','Free','2',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 14:02:39','city',0.00,5.00,2.0,1,0,1,'food'),
(259,20,5,'Mekong River Sunset Fishing','នេសាទត្រី ពេលថ្ងៃលិច','Join local fishermen at sunset on the Mekong near Prey Veng  cast traditional bamboo traps drink palm wine on a wooden boat and watch the sun sink over Vietnam in the distance.','នេសាទត្រី ពេលថ្ងៃលិច ចូលរួមជាមួយអ្នកនេសាទក្នុងស្រុកនៅមេគង្គជិតព្រៃវែង ចាក់បណ្តាប់ឫស្សីបុរាណ ផឹកទឹកដើមត្នោតលើទូកឈើ និងមើលថ្ងៃលិចជិតវៀតណាម។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎣','images/Mekong River Sunset Fishing.jpg','images/Mekong River Sunset Fishing.jpg',NULL,NULL,'Daily evenings','From $10','2',NULL,NULL,NULL,'Easy',0,1,4,'2026-03-21 14:02:39','near',1.00,5.00,2.0,1,0,0,'fun'),
(262,19,5,'Preah Nimith Waterfall Stung Treng','ទឹកជ្រោះ ព្រះនិម្មិត','A spectacular set of Mekong waterfalls near the Laos border  dramatic rapids thunder through granite gorges and the surrounding jungle teems with birds and monkeys.','ទឹកជ្រោះ ព្រះនិម្មិត ទឹកជ្រោះស្អាតជាច្រើននៅមេគង្គជិតព្រំដែនឡាវ ទន្លេរហ័សហែកតាមទន្លេក្រានីត និងព្រៃជុំវិញសម្បូរទាំងសត្វចម្លង និងមក្សី។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💦','images/Preah Nimith Waterfall Stung Treng.jpg','images/Preah Nimith Waterfall Stung Treng.jpg',NULL,NULL,'Daily 6am-5pm','$3','3',NULL,NULL,NULL,'Moderate',1,1,5,'2026-03-21 14:02:39','near',3.00,5.00,2.0,1,0,0,'fun'),
(266,1,1,'Khmer New Year Festival','ពិធីបុណ្យចូលឆ្នាំខ្មែរ','Khmer New Year (Chaul Chnam Thmey) is the most important festival in Cambodia celebrated for 3 days in mid-April. Families gather to pray at temples, perform traditional games, splash water, make offerings to ancestors, and feast together. Cities come alive with music, dancing, and joyful celebrations across every province.','ពិធីបុណ្យចូលឆ្នាំខ្មែរ (ចូលឆ្នាំថ្មី) គឺជាបុណ្យសំខាន់បំផុតនៅកម្ពុជា ដែលប្រារព្ធឡើងរយៈពេល ៣ ថ្ងៃក្នុងពាក់កណ្តាលខែមេសា។ គ្រួសារមកជួបជុំគ្នា ធ្វើបុណ្យនៅវត្ត លេងល្បែងប្រពៃណី ស្ទូចទឹក ថ្វាយបង្គំបុព្វបុរស និងញ៉ាំអាហារជាមួយគ្នា។ ទីក្រុងមានភាពរស់រវើកដោយតន្ត្រី ការរាំ និងការប្រារព្ធពិធីក្រៃលែងនៅគ្រប់ខេត្ត។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🎊','images/Khmer New Year Festival.jpg','images/Khmer New Year Festival.jpg',NULL,NULL,'April 13–15 annually','Free','3 days',NULL,NULL,NULL,'Easy',1,1,50,'2026-03-24 01:46:54','city',0.00,5.00,2.0,1,0,0,'culture'),
(267,1,8,'Pchum Ben Festival','ពិធីបុណ្យភ្ជុំបិណ្ឌ','Pchum Ben (Ancestors Day) is one of the most sacred festivals in Cambodia lasting 15 days. Cambodians visit pagodas at dawn to offer food to monks and make merit for deceased ancestors. Families travel from cities back to their home provinces to pray together and offer sticky rice balls called Bay Ben at temples across the country.','ពិធីបុណ្យភ្ជុំបិណ្ឌ គឺជាពិធីបុណ្យដ៏ឧត្តុង្គឧត្តមមួយ រយៈពេល ១៥ ថ្ងៃ។ ប្រជាជនកម្ពុជាទៅវត្តពេលអរុណ ដើម្បីថ្វាយអាហារដល់ព្រះសង្ឃ និងធ្វើបុណ្យជូនដំណើរបុព្វបុរសដែលបានទទួលមរណភាព។ គ្រួសារធ្វើដំណើរពីទីក្រុងត្រឡប់ទៅខេត្ត ដើម្បីធ្វើបុណ្យជាមួយគ្នា និងថ្វាយបាយបិណ្ឌនៅវត្តក្នុងទូទាំងប្រទេស។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🙏','images/Pchum Ben Festival.jpg','images/Pchum Ben Festival.jpg',NULL,NULL,'September–October (15 days)','Free','15 days',NULL,NULL,NULL,'Easy',1,1,51,'2026-03-24 01:46:54','city',0.00,5.00,2.0,1,0,0,'religious'),
(268,1,8,'Chol Vossa Buddhist Lent','ពិធីបុណ្យចូលព្រះវស្សា','Chol Vossa marks the beginning of Buddhist Lent — a 3-month period when monks remain in their pagodas to study and meditate. Cambodians bring offerings of candles, robes, and food to temples. The celebration includes candlelit processions around pagodas, traditional music, and prayers that light up the night sky across every province in Cambodia.','ពិធីបុណ្យចូលព្រះវស្សា ជាការប្រារព្ធការចាប់ផ្ដើមនៃការចាំវស្សារបស់ព្រះសង្ឃ រយៈពេល ៣ ខែ ដែលព្រះសង្ឃស្នាក់នៅក្នុងវត្ត ដើម្បីសិក្សា និងចែចិត្ត។ ប្រជាជនយកទៀន ចីវរ និងអាហារជូនវត្ត។ ការប្រារព្ធពិធីរួមមានការដង្ហែទៀននៅជុំវិញវត្ត តន្ត្រីប្រពៃណី និងការអធិដ្ឋាន ដែលភ្លឺចាំងព្រះអាទិត្យលិចពេញទូទាំងប្រទេសកម្ពុជា។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕯️','images/Chol Vossa Buddhist Lent.webp','images/Chol Vossa Buddhist Lent.webp',NULL,NULL,'July–October (3 months)','Free','3 months',NULL,NULL,NULL,'Easy',1,1,52,'2026-03-24 01:46:54','city',0.00,5.00,2.0,1,0,0,'religious'),
(269,1,8,'Water Festival','ពិធីបុណ្យអុំទូក','Bon Om Touk, or the Cambodian Water Festival, is a three-day celebration marking the end of the monsoon season and the reversal of the Tonlé Sap River, featuring boat races, spiritual ceremonies, and cultural festivities.','បុណ្យអុំទូក (Bon Om Touk) គឺជាពិធីបុណ្យ​ជាតិដ៏ធំមួយនៅក្នុងប្រទេសកម្ពុជា ដែលកំណត់យក ជាថ្ងៃឈប់សំរាករបស់ពលរដ្ឋកម្ពុជាចំនួន ៣ថ្ងៃ ដែលគិតចាប់ពី អំឡុងខែវិច្ឆិកា និងពេលខ្លះធ្លាក់មកនៅចុងខែតុលា ដែលរាប់តាមប្រតិទិន នៃឆ្នាំចន្ទគតិ ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🚤','images/Water Festival.jpg','images/Water Festival.jpg',NULL,NULL,'November (3 days)','Free','3 days',NULL,NULL,NULL,'Easy',1,1,53,'2026-03-28 03:10:31','city',0.00,5.00,2.0,1,0,0,'religious'),
(270,1,8,'Royal Ploughing Ceremony','ព្រះរាជពិធីច្រត់ព្រះនង្គ័ល','The Royal Ploughing ceremony, which marks the beginning of the crop planting season in the country, was celebrated this morning in Kampong Chhnang province under the royal presidency of His Majesty Preah Bat Samdech Preah Boromneath Norodom Sihamoni, King of Cambodia.','ព្រះរាជពិធី ច្រត់ព្រះនង្គ័លកម្ពុជា (Royal Ploughing Ceremony of Cambodia) គឺជាព្រះរាជពិធីបុណ្យប្រពៃណីជាតិកម្ពុជាមួយ ដែលប្រារព្ធឡើងនៅថ្ងៃ ៤រោច រៀងរាល់ខែ ពិសាខ ត្រូវនិងខែ (ឧសភា) ដែលកំណត់តាម ប្រតិទិនពុទ្ធសាសនា (Buddhist calendar) តាមដំណើរគោលចររបស់ ព្រះចន្ទ ដែលរាប់តាមរង្វាស់នៃឆ្នាំ ចន្ទគតិ (Lunar calendar) នៅក្នុងវប្បធម៌របស់កម្ពុជា ពិធីបុណ្យនេះត្រូវបានគេហៅថា ពិធីបុណ្យចាប់ផ្ដើមនូវរដូវដាំដុះ (Festival begins the growing season) ដែលស្ថាប័នព្រះបរមរាជវាំង និង រៀបចំឱ្យមានកិច្ចភ្ជួរព្រះស្រែដើម្បីជានិមិត្តរូប ក្នុងការចាប់ផ្ដើមរបរកសិកម្ម ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'🕌','images/Royal Ploughing Ceremony.jpg','images/Royal Ploughing Ceremony.jpg',NULL,NULL,'May (1 day)','Free','1 day',NULL,NULL,NULL,'Easy',1,1,54,'2026-03-28 03:10:31','city',0.00,5.00,2.0,1,0,0,'religious'),
(271,1,8,'Festival of Lights','ពិធីបុណ្យបណ្តែតប្រទីប','The Festival of Lights is one of the most beautiful parts of Cambodia’s Water Festival. During this celebration, thousands of colorful lanterns and illuminated boats are released onto rivers, creating a magical scene at night. The lights symbolize happiness, good luck, and gratitude to the water spirits. People gather along the riverbanks to watch the glowing reflections, enjoy traditional music, and celebrate together. This event shows the deep connection between Cambodian culture and the river.','ពិធីបុណ្យបណ្តែតប្រទីប គឺជាផ្នែកដ៏ស្រស់ស្អាតមួយនៃ ព្រះរាជពិធីបុណ្យអុំទូក។ ក្នុងអំឡុងពេលពិធីនេះ ប្រជាជននាំគ្នាបណ្តែតប្រទីប និងទូកតុបតែងដោយភ្លើងពណ៌ចម្រុះលើទឹក បង្កើតទេសភាពអស្ចារ្យនៅពេលយប់។ ពន្លឺទាំងនេះតំណាងឱ្យសុភមង្គល សំណាងល្អ និងការគោរពដល់ទេវតាទឹក។ មនុស្សជាច្រើនប្រមូលផ្តុំគ្នាតាមរង្វង់ទន្លេ ដើម្បីទស្សនាពន្លឺភ្លឺចាំង ស្តាប់តន្ត្រីប្រពៃណី និងអបអរសាទរជាមួយគ្នា។ ព្រឹត្តិការណ៍នេះបង្ហាញពីទំនាក់ទំនងជិតស្និទ្ធរវាងវប្បធម៌ខ្មែរ និងទន្លេ។',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'💡','images/Festival of Lights.jpg','images/Festival of Lights.jpg',NULL,NULL,'November (3 nights)','Free','3 nights',NULL,NULL,NULL,'Easy',1,1,55,'2026-03-28 03:10:31','city',0.00,5.00,2.0,1,0,0,'religious'),
(272,3,1,'Prasat Sneng (Twin Temples)','ប្រាសាទស្នឹង','A pair of ancient temples in Battambang known for brick and sandstone remains, lintel carvings, a front pond and religious heritage.','ប្រាសាទស្នឹង មានប្រាសាទខាងកើត និងខាងលិច សាងពីឥដ្ឋ និងថ្មភក់ មានផ្តែរ ចម្លាក់ បរិវេណស្រះទឹក និងតម្លៃបេតិកភណ្ឌសាសនា។','Twin ancient temples; brick towers; sandstone door frames; front pond; religious heritage','ប្រាសាទបុរាណពីរ; ប៉មឥដ្ឋ; ស៊ុមទ្វារថ្មភក់; ស្រះទឹកមុខប្រាសាទ; ទេសចរណ៍សាសនា','Walk between the east and west temples; view carvings; learn local temple history','Avoid entering unsafe broken structures','Dry season or cool morning','រដូវប្រាំង ឬពេលព្រឹកត្រជាក់','Located in Battambang province; best reached by local vehicle from the city.','🏛️','images/btb/Prasat Sneng (Twin Temples)/1.png','images/btb/Prasat Sneng (Twin Temples)/1.png|images/btb/Prasat Sneng (Twin Temples)/2.jpg|images/btb/Prasat Sneng (Twin Temples)/3.jpg|images/btb/Prasat Sneng (Twin Temples)/4.jpg|images/btb/Prasat Sneng (Twin Temples)/5.png',12.8700000,103.0800000,'Daily','Check locally','1-2 hours','Ancient twin temples and pond','ប្រាសាទបុរាណភ្លោះ និងស្រះទឹក','Basic local services / សេវាមូលដ្ឋាន; bring water / គួរយកទឹកទៅជាមួយ','Easy',0,1,122,'2026-06-22 03:53:43','mid',NULL,4.00,1.5,1,0,0,'culture,temple,history,religion'),
(273,3,1,'Prasat Basset','ប្រាសាទបាសែត','An 11th-century cultural temple site from the Suryavarman I era, with ancient foundations, a pond and quiet countryside around it.','ប្រាសាទបាសែត ជារមណីយដ្ឋានវប្បធម៌សតវត្សទី១១ ក្នុងសម័យព្រះបាទសូរ្យវរ្ម័នទី១ មានសំណល់ប្រាសាទ ស្រះបុរាណ និងទេសភាពជនបទ។','11th-century temple; ancient pond; Suryavarman I era; quiet countryside','ប្រាសាទសតវត្សទី១១; ស្រះបុរាណ; សម័យសូរ្យវរ្ម័នទី១; ទេសភាពជនបទ','Explore the temple site; view the pond; combine with nearby heritage stops','Avoid littering and protect remaining stones','Morning or late afternoon','ពេលព្រឹក ឬល្ងាច','Travel by tuk-tuk, car or motorbike from Battambang city.','🏛️','images/btb/Prasat Basset/1.jpg','images/btb/Prasat Basset/1.jpg|images/btb/Prasat Basset/2.jpg|images/btb/Prasat Basset/3.png|images/btb/Prasat Basset/4.jpg|images/btb/Prasat Basset/5.png|images/btb/Prasat Basset/6.jpg|images/btb/Prasat Basset/7.jpg|images/btb/Prasat Basset/8.jpg|images/btb/Prasat Basset/9.jpg|images/btb/Prasat Basset/10.jpg|images/btb/Prasat Basset/11.jpg',13.0600000,103.1400000,'Daily','Check locally','1-2 hours','Ancient temple and heritage pond','ប្រាសាទបុរាណ និងស្រះបេតិកភណ្ឌ','Basic local services / សេវាមូលដ្ឋាន; bring snacks / គួរយកអាហារសម្រន់ទៅជាមួយ','Easy',0,1,123,'2026-06-22 03:53:43','mid',NULL,4.00,1.5,1,1,0,'culture,temple,history'),
(274,3,2,'Chamkar Mien (Mien Farm)','ចំការមៀន','A fruit-farm tourism stop with riverside scenery, orchard views and a relaxed countryside atmosphere.','ចំការមៀន ជាតំបន់កសិទេសចរណ៍ មានទេសភាពអមមាត់ស្ទឹង ច្រាំងស្ទឹង សកម្មភាពតាមដងស្ទឹង និងចម្ការផ្លែឈើ។','Longan farm; riverside scenery; orchard views; countryside activities','ចំការមៀន; ទេសភាពមាត់ស្ទឹង; ច្រាំងស្ទឹង; សកម្មភាពជនបទ','Walk through the orchard; taste seasonal fruit; relax by the stream','Ask before picking fruit and keep the farm clean','Fruit season and cool morning','រដូវផ្លែឈើ និងពេលព្រឹក','Travel by local road from Battambang city or nearby districts.','🌳','images/btb/Chamkar Mien (Mien Farm)/1.jpg','images/btb/Chamkar Mien (Mien Farm)/1.jpg|images/btb/Chamkar Mien (Mien Farm)/2.jpg|images/btb/Chamkar Mien (Mien Farm)/3.jpg|images/btb/Chamkar Mien (Mien Farm)/4.jpg|images/btb/Chamkar Mien (Mien Farm)/5.jpg|images/btb/Chamkar Mien (Mien Farm)/6.jpg',12.7800000,103.0700000,'Seasonal','Check locally','1-2 hours','Longan farm and riverside scenery','ចំការមៀន និងទេសភាពមាត់ស្ទឹង','Food &amp; drink / ម្ហូបអាហារ និងភេសជ្ជៈ; seasonal fruit / ផ្លែឈើតាមរដូវ','Easy',0,1,128,'2026-06-22 03:53:43','mid',NULL,5.00,1.5,1,1,1,'nature,food,farm,relax'),
(275,3,2,'Chamkar Svaay Waterfall (Samlout)','ទឹកធ្លាក់ចំការស្វាយ','A Samlout nature site with streamside views, forest hills and refreshing waterfall scenery.','ទឹកធ្លាក់ចំការស្វាយ ជាតំបន់ធម្មជាតិស្រុកសំឡូត មានទឹកធ្លាក់ ទេសភាពដងស្ទឹង ច្រាំងមាត់ស្ទឹង និងព្រៃភ្នំស្រស់ស្អាត។','Waterfall; stream bank views; forest hills; nature picnic area','ទឹកធ្លាក់; ទេសភាពដងស្ទឹង; ច្រាំងមាត់ស្ទឹង; ព្រៃភ្នំ; កន្លែងសម្រាកធម្មជាតិ','Relax by the stream; take waterfall photos; picnic with friends or family','Be careful on wet rocks and avoid visiting during heavy rain','Rainy season for water flow, dry season for easier access','រដូវវស្សាសម្រាប់ទឹកច្រើន រដូវប្រាំងសម្រាប់ផ្លូវងាយ','Travel toward Samlout district; local vehicle or motorbike is recommended.','💧','images/btb/Chamkar Svaay Waterfall (Samlout)/1.jpg','images/btb/Chamkar Svaay Waterfall (Samlout)/1.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/2.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/3.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/4.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/5.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/6.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/7.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/8.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/9.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/10.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/11.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/12.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/13.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/14.jpg|images/btb/Chamkar Svaay Waterfall (Samlout)/15.jpg',12.4500000,102.9200000,'Check locally','Check locally','2-3 hours','Waterfall and forest stream','ទឹកធ្លាក់ និងស្ទឹងព្រៃភ្នំ','Food &amp; drink may be limited / ម្ហូបអាហារ និងភេសជ្ជៈអាចមានកំណត់; bring picnic / អាចយកអាហារទៅបរិភោគ','Moderate',0,1,127,'2026-06-22 03:53:43','far',NULL,5.00,2.5,1,1,0,'nature,waterfall,picnic,mountain'),
