INSERT INTO "festivals" ("id", "place_id", "name_en", "name_kh", "icon", "description_en", "description_kh", "vibe_en", "when_en", "duration_en", "accent_color", "provinces", "is_active", "sort_order", "created_at") VALUES
(1,266,'Khmer New Year','ពិធីបុណ្យចូលឆ្នាំខ្មែរ','🎊','The most important festival in Cambodia. Families reunite, visit temples, and celebrate with traditional games and water festivities.','ពិធីបុណ្យចូលឆ្នាំខ្មែរ ជាពិធីបុណ្យសំខាន់បំផុតនៅប្រទេសកម្ពុជា។ គ្រួសារបានមកជួបជុំគ្នា ប្រារព្ធពិធីទាំងការលេងទឹក និងការទៅលេងវត្តនិងផ្សេងៗទៀត។','Joyful · Water · Family','April 13–15','3 days','#C8922A','[{"code": "ALL", "name": "Nationwide", "color": "#8B4513", "primary": true}]',1,1,'2026-03-26 05:01:49'),
(2,267,'Pchum Ben','ពិធីបុណ្យភ្ជុំបិណ្ឌ','🙏','Ancestors’ Day in Cambodia. Families visit pagodas and offer food to honor ancestors.','ពិធីបុណ្យភ្ជុំបិណ្ឌ ប្រជាជនទៅវត្តដើម្បីឧទ្ទិសដល់បុព្វបុរស។','Spiritual · Offering','September – October','15 days','#CC1F27','[{"code": "ALL", "name": "Nationwide", "color": "#666", "primary": true}]',1,2,'2026-03-26 05:01:49'),
(3,268,'Chol Vossa','ពិធីបុណ្យចូលព្រះវស្សា','🕯️','Beginning of Buddhist Lent. Monks stay in temples for study and meditation.','ពិធីចូលព្រះវស្សា ព្រះសង្ឃស្នាក់នៅវត្ត៣ខែ។','Religious · Calm','July – October','3 months','#1A4A7A','[{"code": "ALL", "name": "Nationwide", "color": "#1A4A7A", "primary": true}]',1,3,'2026-03-26 05:01:49'),
(4,NULL,'Water Festival','ពិធីបុណ្យអុំទូក','🚤','Boat racing festival with millions of visitors in Phnom Penh.','បុណ្យប្រណាំងទូកមានមនុស្សច្រើន។','Boat · Festival','Nov','3 days','#1B5E3B','[{"code": "PP", "name": "Phnom Penh", "color": "#CC1F27", "primary": true}]',1,4,'2026-03-26 05:01:49'),
(5,NULL,'Royal Ploughing Ceremony','ព្រះរាជពិធីច្រត់ព្រះនង្គ័ល','🕌','Royal ceremony predicting rice harvest.','ពិធីព្រះរាជទាក់ទងនឹងកសិកម្ម។','Royal · Agriculture','May','1 day','#8B4513','[{"code": "PP", "name": "Phnom Penh", "color": "#CC1F27", "primary": true}]',1,5,'2026-03-26 05:01:49'),
(6,NULL,'Festival of Lights','ពិធីបុណ្យបណ្តែតប្រទីប','💡','Lanterns and lights on water during Water Festival.','ប្រទីបលើទឹកពេលយប់។','Light · Night','Nov','3 nights','#C8922A','[{"code": "PP", "name": "Phnom Penh", "color": "#CC1F27", "primary": true}]',1,6,'2026-03-26 05:01:49');
