(397,'Battambang',3,'','Riverside BBQ Street Food Strip','ហាងអាំង មាត់ស្ទឹង','street_food','Evening riverside stalls: grilled corn, lok lak, grilled pork, fresh sugarcane juice. Lively 5pm-midnight.',NULL,NULL,NULL,1,2,NULL,NULL,NULL,'$1-4',NULL,NULL),
(398,'Battambang',3,'','Mi Kola Stalls','ហាងមីកូឡា','street_food','Battambang signature dry noodle — pork, bean sprouts, peanut sauce. Near Phsar Nath or Phsar Thmey.',NULL,NULL,NULL,1,3,NULL,NULL,NULL,'$1-2',NULL,NULL),
(399,'Battambang',3,'','White Rose Restaurant','ភោជនីយដ្ឋាន ផ្កាកុលាបស','local','Long-running Battambang restaurant known by travelers for Khmer and casual local dishes.',NULL,NULL,NULL,1,1,'',NULL,NULL,'$2-7',NULL,NULL),
(400,'Battambang',3,'','Cafe Eden','កាហ្វេ អេដែន','cafe','Cafe and restaurant option in Battambang with coffee, Western dishes, and casual meals.',NULL,NULL,NULL,1,2,'',NULL,NULL,'$3-8',NULL,NULL),
(401,'Battambang',3,'Phnom Sampeau & Bat Caves','Phnom Sampeau Food & Drink Stalls','តូបអាហារ និងភេសជ្ជៈ ភ្នំសំពៅ','street_food','Food and drink stalls around Phnom Sampeau and the bat cave area. This is a local food area, not one fixed restaurant listing.',NULL,NULL,NULL,0,1,'',NULL,NULL,'$1-5',NULL,NULL),
(402,'Battambang',3,'','The Balcony Battambang','ឌឹ បាល់ខូនី បាត់ដំបង','western','Restaurant and bar option in Battambang, suitable for dinner, drinks, and groups.',NULL,NULL,NULL,1,2,'',NULL,NULL,'$4-12',NULL,NULL),
(404,'Battambang',3,'','Smokin Pot Restaurant','ស្ម៉ូគីន ប៉ុត','western','Western and Khmer dishes plus Khmer cooking classes. Near the old market.',NULL,NULL,NULL,1,2,NULL,NULL,'https://www.facebook.com/smokinpotbattambang','$4-12',NULL,NULL),
(406,'Battambang',3,'','Battambang Cafe and Bar','កាហ្វេ និងបារ បាត់ដំបង','cafe','Cafe and bar option in Battambang for coffee, light meals, and evening drinks.',NULL,NULL,NULL,1,1,'',NULL,NULL,'$2-7',NULL,NULL),
(408,'Battambang',3,'','THE PLACE Restaurant Cafe Bar','ឌឹ ផ្លេស ភោជនីយដ្ឋាន កាហ្វេ និងបារ','vegetarian','Restaurant, cafe, and bar in Battambang with vegetarian and vegan-friendly choices.',NULL,NULL,NULL,1,1,'',NULL,NULL,'$3-9',NULL,NULL),
