INSERT INTO "province_shops" ("id", "province_id", "slug", "name_en", "name_kh", "shop_type", "description_en", "description_kh", "merchandise_en", "merchandise_kh", "address_en", "address_kh", "opening_hours", "price_level", "image_url", "images", "latitude", "longitude", "map_query", "phone", "website_url", "source_url", "verified_at", "is_active", "sort_order", "created_at", "updated_at") VALUES
(1,3,'phsar-nath-central-market','Phsar Nath Central Market','ផ្សារណាត់','traditional_market','Battambang city centre''s landmark traditional market, useful for everyday fashion, footwear, food, gifts and household shopping.','ផ្សារប្រពៃណីសំខាន់នៅកណ្ដាលក្រុងបាត់ដំបង សម្រាប់ទិញសម្លៀកបំពាក់ ស្បែកជើង អាហារ អំណោយ និងសម្ភារៈប្រើប្រាស់។','Clothes|Shoes & sandals|Jewelry|Fresh produce|Groceries|Street food|Household goods','សម្លៀកបំពាក់|ស្បែកជើង និងស្បែកជើងផ្ទាត់|គ្រឿងអលង្ការ|បន្លែផ្លែឈើ|គ្រឿងទេស|អាហារតាមផ្លូវ|សម្ភារៈផ្ទះ','Street 113, Battambang city centre','ផ្លូវ ១១៣ កណ្ដាលក្រុងបាត់ដំបង','Daily 5:00am–6:30pm','budget',NULL,NULL,NULL,NULL,'Phsar Nath Market, Battambang, Cambodia',NULL,NULL,'https://www.tourismcambodia.com/travelguides/provinces/battambang/shopping.htm','2026-07-20',1,10,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(2,3,'boeung-chhouk-market','Boeung Chhouk Market','ផ្សារបឹងឈូក','traditional_market','A large local market with mixed goods and extensive produce sections, popular for practical everyday shopping.','ផ្សារធំសម្រាប់អ្នកស្រុក មានទំនិញចម្រុះ និងផ្នែកបន្លែផ្លែឈើធំ សមស្របសម្រាប់ការទិញទំនិញប្រចាំថ្ងៃ។','Clothes|Fabrics|Jewelry|Groceries|Fresh produce|Meat & seafood|Local food','សម្លៀកបំពាក់|ក្រណាត់|គ្រឿងអលង្ការ|គ្រឿងទេស|បន្លែផ្លែឈើ|សាច់ និងគ្រឿងសមុទ្រ|អាហារខ្មែរ','454W+26J, Street 110, Battambang','ផ្លូវ ១១០ ក្រុងបាត់ដំបង','Daily 6:00am–6:00pm','budget',NULL,NULL,NULL,NULL,'Boeung Chhouk Market, Battambang, Cambodia',NULL,NULL,'https://wastemanagement.gov.kh/wp-content/uploads/2016/10/1.-CT1-Initial-Environmental-Examination-Update-Jan-2020.pdf','2026-07-20',1,20,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(3,3,'phsar-leu-battambang','Phsar Leu Battambang','ផ្សារលើបាត់ដំបង','traditional_market','A traditional market south of the centre known for local produce and regional fruit alongside mixed everyday goods.','ផ្សារប្រពៃណីនៅខាងត្បូងក្រុង ល្បីដោយបន្លែផ្លែឈើក្នុងស្រុក និងទំនិញប្រើប្រាស់ចម្រុះ។','Local fruit|Oranges & pomelos|Fresh produce|Groceries|Clothes|Household goods','ផ្លែឈើក្នុងស្រុក|ក្រូច និងក្រូចថ្លុង|បន្លែផ្លែឈើ|គ្រឿងទេស|សម្លៀកបំពាក់|សម្ភារៈផ្ទះ','South Battambang city','ខាងត្បូងក្រុងបាត់ដំបង','Daily 6:00am–6:00pm','budget',NULL,NULL,NULL,NULL,'Phsar Leu Market, Battambang, Cambodia',NULL,NULL,'https://www.battambang.com/battambang-essentials/','2026-07-20',1,30,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(4,3,'battambang-night-market','Battambang Night Market','ផ្សាររាត្រីបាត់ដំបង','night_market','A relaxed evening market near the river for affordable clothing, souvenirs, crafts, snacks and local street food.','ផ្សាររាត្រីក្បែរមាត់ទន្លេ សម្រាប់ទិញសម្លៀកបំពាក់ អនុស្សាវរីយ៍ សិប្បកម្ម អាហារសម្រន់ និងម្ហូបតាមផ្លូវ។','Clothes|Souvenirs|Handmade crafts|Jewelry|Toys|Street food','សម្លៀកបំពាក់|វត្ថុអនុស្សាវរីយ៍|សិប្បកម្មធ្វើដោយដៃ|គ្រឿងអលង្ការ|ប្រដាប់ក្មេងលេង|អាហារតាមផ្លូវ','Sangker riverside, Battambang','មាត់ស្ទឹងសង្កែ ក្រុងបាត់ដំបង','Daily, approximately 5:00pm–11:00pm','budget','images/btb_nightmarket.webp',NULL,NULL,NULL,'Battambang Night Market, Cambodia',NULL,NULL,'https://www.holidify.com/places/battambang/night-markets-battambang-sightseeing-1256502.html','2026-07-20',1,40,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(5,3,'la-fabrik','La Fabrik','ឡា ហ្វាប្រីក','boutique','A boutique focused on locally made gifts, jewelry, natural body products and Cambodian delicatessen items.','ហាងប៊ូទិកដែលផ្តោតលើអំណោយផលិតក្នុងស្រុក គ្រឿងអលង្ការ ផលិតផលថែរក្សារាងកាយធម្មជាតិ និងផលិតផលម្ហូបកម្ពុជា។','Local jewelry|Accessories|Souvenirs|Natural soaps & scrubs|Coffee & tea|Cambodian spirits','គ្រឿងអលង្ការក្នុងស្រុក|គ្រឿងតុបតែង|វត្ថុអនុស្សាវរីយ៍|សាប៊ូ និងស្ក្រាប់ធម្មជាតិ|កាហ្វេ និងតែ|ស្រាកម្ពុជា','65 Street 2.5, Walking District, Battambang','ផ្ទះលេខ ៦៥ ផ្លូវ ២.៥ តំបន់ដើរលេង បាត់ដំបង','Mon–Sat 9:00am–9:00pm; Sun 4:00pm–8:00pm; seasonal closure May–Jun','mid',NULL,NULL,NULL,NULL,'La Fabrik, Street 2.5, Battambang, Cambodia','096 774 4225','https://www.battambang.com/shopping/la-fabrik/','https://www.battambang.com/shopping/la-fabrik/','2026-07-20',1,50,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(6,3,'silk-and-soul-ethnic-shop','Silk & Soul Ethnic Shop','ហាង ស៊ីល និង សូល','handicraft','A local-product boutique inside Maisons Wat Kor featuring community crafts, regional food products and work by young artists.','ហាងផលិតផលក្នុងស្រុកនៅ Maisons Wat Kor មានសិប្បកម្មសហគមន៍ ផលិតផលអាហារក្នុងតំបន់ និងស្នាដៃសិល្បៈរបស់យុវជន។','Handmade crafts|Local oils|Samlot black pepper|Paintings|Community products|Souvenirs','សិប្បកម្មធ្វើដោយដៃ|ប្រេងក្នុងស្រុក|ម្រេចខ្មៅសំឡូត|គំនូរ|ផលិតផលសហគមន៍|វត្ថុអនុស្សាវរីយ៍','Maisons Wat Kor, Wat Kor Village, Battambang','Maisons Wat Kor ភូមិវត្តគរ បាត់ដំបង','Check with Maisons Wat Kor','mid',NULL,NULL,NULL,NULL,'Silk and Soul Ethnic Shop, Maisons Wat Kor, Battambang',NULL,'https://maisonswatkor.com/rooms/boutique/','https://maisonswatkor.com/rooms/boutique/','2026-07-20',1,60,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(7,3,'laey-baitong','Laey Baitong','ល្អីបៃតង','local_products','A Battambang social-enterprise shop selling safe, fresh products sourced from local farmers and older farming communities.','ហាងសហគ្រាសសង្គមនៅបាត់ដំបង លក់ផលិតផលស្រស់ និងមានសុវត្ថិភាពពីកសិករក្នុងស្រុក និងសហគមន៍កសិករវ័យចាស់។','Local vegetables|Fresh fruit|Rice|Safe food products|Farmer products|Organic groceries','បន្លែក្នុងស្រុក|ផ្លែឈើស្រស់|អង្ករ|ផលិតផលអាហារមានសុវត្ថិភាព|ផលិតផលកសិករ|គ្រឿងទេសសរីរាង្គ','#272, Street 207, Kampong Krabei, Svay Por, Battambang','#២៧២ ផ្លូវ ២០៧ កំពង់ក្របី ស្វាយប៉ោ បាត់ដំបង','Check locally','mid',NULL,NULL,NULL,NULL,'Laey Baitong, Battambang, Cambodia',NULL,'https://www.laeybaitong.com/','https://www.laeybaitong.com/','2026-07-20',1,70,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(8,3,'baitang-retail','Baitang Retail','ហាងបៃតង','local_products','A Battambang retail outlet for locally produced premium jasmine and fragrant rice, with local delivery available.','ហាងលក់រាយនៅបាត់ដំបង សម្រាប់អង្ករផ្កាម្លិះ និងអង្ករក្រអូបគុណភាពខ្ពស់ផលិតក្នុងស្រុក និងមានសេវាដឹកជញ្ជូន។','Jasmine rice|Fragrant rice|Local rice products|Food gifts','អង្ករផ្កាម្លិះ|អង្ករក្រអូប|ផលិតផលអង្ករក្នុងស្រុក|អំណោយអាហារ','Battambang city retail outlet','ហាងលក់រាយក្រុងបាត់ដំបង','Check locally','mid',NULL,NULL,NULL,NULL,'Baitang Retail, Battambang, Cambodia','098 264 488','https://baitangplcrice.com/contact-us/','https://baitangplcrice.com/contact-us/','2026-07-20',1,80,'2026-07-20 06:14:54','2026-07-20 06:14:54'),
(9,3,'lao-chhay-try-dress-shoes','Lao Chhay Try Modern Dress & Shoes Shop','ហាងសម្លៀកបំពាក់ និងស្បែកជើង ឡាវ ឆាយ ទ្រី','fashion','A dedicated local fashion shop for modern clothing and footwear in central Battambang.','ហាងម៉ូដក្នុងស្រុកសម្រាប់សម្លៀកបំពាក់ទាន់សម័យ និងស្បែកជើងនៅកណ្ដាលក្រុងបាត់ដំបង។','Modern clothes|Shoes|Sandals|Fashion accessories','សម្លៀកបំពាក់ទាន់សម័យ|ស្បែកជើង|ស្បែកជើងផ្ទាត់|គ្រឿងតុបតែងម៉ូដ','No. 49–51, Street 3, 20 Usaphea Village, Battambang','លេខ ៤៩–៥១ ផ្លូវ ៣ ភូមិ ២០ ឧសភា បាត់ដំបង','Check locally','budget',NULL,NULL,NULL,NULL,'Lao Chhay Try Modern Dress Shoes Shop, Battambang, Cambodia','053 952 211',NULL,'https://www.cambodiayp.com/category/Shoes/city%3ABattambang','2026-07-20',1,90,'2026-07-20 06:14:54','2026-07-20 06:14:54');
