-- PostgreSQL version of travel_kh (converted from MariaDB 10.4 dump)
-- Usage: createdb travel_kh && psql -d travel_kh -f travel_kh_postgres.sql

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

BEGIN;


-- ===== Schema =====

CREATE TABLE "admin_users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "username" varchar(100) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "admin_users_username_key" UNIQUE ("username")
);

CREATE TABLE "bookmarks" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "place_id" integer NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "bookmarks_uq_bk_key" UNIQUE ("user_id", "place_id")
);

CREATE TABLE "categories" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "slug" varchar(50) NOT NULL,
  "name_en" varchar(100) NOT NULL,
  "name_kh" varchar(100) NOT NULL,
  "icon" varchar(10) NOT NULL,
  "color" varchar(20) NOT NULL,
  "sort_order" integer DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "categories_slug_key" UNIQUE ("slug")
);

CREATE TABLE "donations" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "donor_name" varchar(150) DEFAULT 'Anonymous',
  "amount_usd" decimal(8,2) NOT NULL,
  "message" text DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','completed')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "festivals" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "place_id" integer DEFAULT NULL,
  "name_en" varchar(120) NOT NULL,
  "name_kh" varchar(200) DEFAULT NULL,
  "icon" varchar(10) DEFAULT '?',
  "description_en" text DEFAULT NULL,
  "description_kh" text DEFAULT NULL,
  "vibe_en" varchar(200) DEFAULT NULL,
  "when_en" varchar(100) DEFAULT NULL,
  "duration_en" varchar(60) DEFAULT NULL,
  "accent_color" varchar(10) DEFAULT '#C8922A',
  "provinces" jsonb DEFAULT NULL,
  "is_active" smallint DEFAULT 1,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "guide_applications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "name" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "email" varchar(120) NOT NULL,
  "telegram" varchar(80) DEFAULT NULL,
  "dob" date DEFAULT NULL,
  "gender" varchar(20) DEFAULT NULL CHECK ("gender" IN ('male','female','other')),
  "id_card_no" varchar(60) NOT NULL,
  "id_card_photo" varchar(400) DEFAULT NULL,
  "home_address" text NOT NULL,
  "provinces" varchar(500) DEFAULT NULL,
  "languages" varchar(255) DEFAULT NULL,
  "years_exp" smallint DEFAULT 0,
  "daily_rate_usd" decimal(8,2) DEFAULT NULL,
  "bio" text DEFAULT NULL,
  "profile_photo" varchar(400) DEFAULT NULL,
  "warranty_letter" varchar(400) DEFAULT NULL,
  "guarantor_name" varchar(120) DEFAULT NULL,
  "guarantor_phone" varchar(40) DEFAULT NULL,
  "guarantor_id" varchar(60) DEFAULT NULL,
  "guarantor_rel" varchar(80) DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "guide_bookings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "reference" varchar(20) NOT NULL,
  "guide_id" integer DEFAULT NULL,
  "tourist_name" varchar(120) NOT NULL,
  "nationality" varchar(80) DEFAULT NULL,
  "email" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "home_address" text NOT NULL,
  "passport_no" varchar(60) DEFAULT NULL,
  "passport_photo" varchar(400) DEFAULT NULL,
  "id_card_no" varchar(60) DEFAULT NULL,
  "id_card_photo" varchar(400) DEFAULT NULL,
  "trip_start" date NOT NULL,
  "trip_end" date NOT NULL,
  "num_people" smallint DEFAULT 1,
  "trip_plan" text NOT NULL,
  "special_requests" text DEFAULT NULL,
  "total_usd" decimal(10,2) NOT NULL,
  "deposit_usd" decimal(10,2) NOT NULL,
  "balance_usd" decimal(10,2) NOT NULL,
  "payment_status" varchar(20) DEFAULT 'pending' CHECK ("payment_status" IN ('pending','pending_review','deposit_paid','fully_paid','refunded','expired')),
  "payment_due_at" timestamp DEFAULT NULL,
  "paid_at" timestamp DEFAULT NULL,
  "payment_reference" varchar(80) DEFAULT NULL,
  "payment_proof" varchar(255) DEFAULT NULL,
  "booking_status" varchar(20) DEFAULT 'pending' CHECK ("booking_status" IN ('pending','confirmed','in_progress','completed','cancelled')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "guide_bookings_reference_key" UNIQUE ("reference")
);

CREATE TABLE "guides" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "email" varchar(120) DEFAULT NULL,
  "telegram" varchar(80) DEFAULT NULL,
  "bio" text DEFAULT NULL,
  "languages" varchar(255) DEFAULT 'Khmer, English',
  "provinces" varchar(500) DEFAULT NULL,
  "daily_rate_usd" decimal(8,2) DEFAULT NULL,
  "years_exp" smallint DEFAULT 0,
  "profile_photo" varchar(400) DEFAULT NULL,
  "id_card_no" varchar(60) DEFAULT NULL,
  "id_card_photo" varchar(400) DEFAULT NULL,
  "guarantor_name" varchar(120) DEFAULT NULL,
  "guarantor_phone" varchar(40) DEFAULT NULL,
  "guarantor_id" varchar(60) DEFAULT NULL,
  "guarantor_rel" varchar(80) DEFAULT NULL,
  "warranty_letter" varchar(400) DEFAULT NULL,
  "dob" date DEFAULT NULL,
  "gender" varchar(20) DEFAULT NULL CHECK ("gender" IN ('male','female','other')),
  "home_address" text DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected','suspended')),
  "is_active" smallint DEFAULT 0,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "hotel_restaurant_reservations" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "item_type" varchar(20) NOT NULL CHECK ("item_type" IN ('hotel','restaurant')),
  "hotel_id" integer DEFAULT NULL,
  "restaurant_id" integer DEFAULT NULL,
  "item_name" varchar(200) NOT NULL,
  "province_id" integer DEFAULT NULL,
  "tourist_name" varchar(120) NOT NULL,
  "phone" varchar(60) NOT NULL,
  "email" varchar(160) DEFAULT NULL,
  "reserve_date" date DEFAULT NULL,
  "reserve_time" varchar(20) DEFAULT NULL,
  "check_out_date" date DEFAULT NULL,
  "guests" integer DEFAULT 1,
  "rooms" integer DEFAULT 1,
  "room_type" varchar(80) DEFAULT NULL,
  "meal_type" varchar(80) DEFAULT NULL,
  "table_request" varchar(80) DEFAULT NULL,
  "payment_method" varchar(80) DEFAULT NULL,
  "payment_note" varchar(200) DEFAULT NULL,
  "price_range" varchar(80) DEFAULT NULL,
  "estimated_price_usd" decimal(10,2) DEFAULT NULL,
  "estimated_commission_usd" decimal(10,2) DEFAULT NULL,
  "notes" text DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','confirmed','completed','cancelled')),
  "payment_status" varchar(20) DEFAULT 'not_due' CHECK ("payment_status" IN ('not_due','unpaid','pending_review','paid','expired')),
  "payment_due_at" timestamp DEFAULT NULL,
  "paid_at" timestamp DEFAULT NULL,
  "payment_amount_usd" decimal(10,2) DEFAULT NULL,
  "price_per_night_usd" decimal(10,2) DEFAULT NULL,
  "nights" integer DEFAULT 1,
  "room_number" varchar(80) DEFAULT NULL,
  "booking_details" text DEFAULT NULL,
  "included_features" text DEFAULT NULL,
  "payment_reference" varchar(80) DEFAULT NULL,
  "payment_proof" varchar(255) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "hotels" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "province_id" integer NOT NULL,
  "name" varchar(200) NOT NULL,
  "type" varchar(20) DEFAULT 'Hotel' CHECK ("type" IN ('Hotel','Guesthouse','Hostel','Resort','Homestay')),
  "price_range" varchar(80) DEFAULT NULL,
  "rating" decimal(2,1) DEFAULT NULL,
  "address" varchar(300) DEFAULT NULL,
  "amenities" varchar(400) DEFAULT NULL,
  "image_url" varchar(300) DEFAULT NULL,
  "images" text DEFAULT NULL,
  "is_active" smallint DEFAULT 1,
  "sort_order" integer DEFAULT 0,
  "latitude" decimal(10,7) DEFAULT NULL,
  "longitude" decimal(10,7) DEFAULT NULL,
  "contact_number" varchar(50) DEFAULT NULL,
  "telegram_link" varchar(255) DEFAULT NULL,
  "facebook_url" varchar(255) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "place_restaurants" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "province_name" varchar(100) NOT NULL,
  "province_id" integer DEFAULT NULL,
  "place_name" varchar(100) NOT NULL,
  "restaurant_name_en" varchar(150) NOT NULL,
  "restaurant_name_kh" varchar(255) NOT NULL,
  "cuisine_type" varchar(50) DEFAULT 'local',
  "description_en" text DEFAULT NULL,
  "image_url" varchar(300) DEFAULT NULL,
  "images" text DEFAULT NULL,
  "opening_hours" varchar(150) DEFAULT NULL,
  "is_province_wide" smallint DEFAULT 0,
  "sort_order" integer NOT NULL,
  "contact_number" varchar(50) DEFAULT NULL,
  "telegram_link" varchar(255) DEFAULT NULL,
  "facebook_url" varchar(255) DEFAULT NULL,
  "price_range" varchar(50) DEFAULT NULL,
  "latitude" decimal(10,8) DEFAULT NULL,
  "longitude" decimal(11,8) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "places" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "province_id" integer NOT NULL,
  "category_id" integer NOT NULL,
  "name_en" varchar(200) NOT NULL,
  "name_kh" varchar(200) NOT NULL,
  "description_en" text DEFAULT NULL,
  "description_kh" text DEFAULT NULL,
  "highlights_en" text DEFAULT NULL,
  "highlights_kh" text DEFAULT NULL,
  "things_to_do_en" text DEFAULT NULL,
  "things_avoid_en" text DEFAULT NULL,
  "best_time_en" varchar(300) DEFAULT NULL,
  "best_time_kh" varchar(300) DEFAULT NULL,
  "getting_there_en" text DEFAULT NULL,
  "icon" varchar(10) DEFAULT '?',
  "image_url" varchar(500) DEFAULT NULL,
  "images" text DEFAULT NULL,
  "latitude" decimal(10,7) DEFAULT NULL,
  "longitude" decimal(10,7) DEFAULT NULL,
  "opening_hours" varchar(200) DEFAULT NULL,
  "entry_fee" varchar(100) DEFAULT NULL,
  "duration" varchar(100) DEFAULT NULL,
  "main_product_en" varchar(200) DEFAULT NULL,
  "main_product_kh" varchar(200) DEFAULT NULL,
  "services_en" varchar(500) DEFAULT NULL,
  "difficulty" varchar(20) DEFAULT 'Easy' CHECK ("difficulty" IN ('Easy','Moderate','Challenging')),
  "is_featured" smallint DEFAULT 0,
  "is_active" smallint DEFAULT 1,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "zone" varchar(20) DEFAULT 'near' CHECK ("zone" IN ('city','near','mid','far')),
  "entry_fee_usd" decimal(8,2) DEFAULT NULL,
  "estimated_food_usd" decimal(8,2) DEFAULT 5.00,
  "avg_visit_hrs" decimal(4,1) DEFAULT 2.0,
  "kids_friendly" smallint DEFAULT 1,
  "picnic_friendly" smallint DEFAULT 0,
  "on_site_food" smallint DEFAULT 0,
  "planner_tags" varchar(255) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "point_redemptions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "reward_id" integer NOT NULL,
  "reward_name" varchar(160) NOT NULL,
  "cost_points" integer NOT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','approved','completed','cancelled')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "point_rewards" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name_en" varchar(120) NOT NULL,
  "name_kh" varchar(120) DEFAULT NULL,
  "description_en" varchar(255) DEFAULT NULL,
  "cost_points" integer NOT NULL,
  "is_active" smallint NOT NULL DEFAULT 1,
  "sort_order" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "province_shops" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "province_id" integer NOT NULL,
  "slug" varchar(120) NOT NULL,
  "name_en" varchar(180) NOT NULL,
  "name_kh" varchar(255) NOT NULL,
  "shop_type" varchar(50) NOT NULL DEFAULT 'market',
  "description_en" text DEFAULT NULL,
  "description_kh" text DEFAULT NULL,
  "merchandise_en" text DEFAULT NULL,
  "merchandise_kh" text DEFAULT NULL,
  "address_en" varchar(350) DEFAULT NULL,
  "address_kh" varchar(350) DEFAULT NULL,
  "opening_hours" varchar(180) DEFAULT NULL,
  "price_level" varchar(30) DEFAULT NULL,
  "image_url" varchar(500) DEFAULT NULL,
  "images" text DEFAULT NULL,
  "latitude" decimal(10,7) DEFAULT NULL,
  "longitude" decimal(10,7) DEFAULT NULL,
  "map_query" varchar(350) DEFAULT NULL,
  "phone" varchar(60) DEFAULT NULL,
  "website_url" varchar(500) DEFAULT NULL,
  "source_url" varchar(500) DEFAULT NULL,
  "verified_at" date DEFAULT NULL,
  "is_active" smallint NOT NULL DEFAULT 1,
  "sort_order" integer NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "province_shops_uq_province_shop_slug_key" UNIQUE ("province_id", "slug")
);

CREATE TABLE "provinces" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "slug" varchar(80) NOT NULL,
  "name_en" varchar(150) NOT NULL,
  "name_kh" varchar(150) NOT NULL,
  "region" varchar(20) NOT NULL CHECK ("region" IN ('Northwest','Northeast','Central','Southwest','Coast','East')),
  "description_en" text DEFAULT NULL,
  "description_kh" text DEFAULT NULL,
  "emoji" varchar(10) DEFAULT '?️',
  "cover_color" varchar(20) DEFAULT '#7A3B10',
  "cover_image" varchar(500) DEFAULT NULL,
  "latitude" decimal(10,7) DEFAULT NULL,
  "longitude" decimal(10,7) DEFAULT NULL,
  "is_featured" smallint DEFAULT 0,
  "sort_order" integer DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "provinces_slug_key" UNIQUE ("slug")
);

CREATE TABLE "restaurant_menu_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "restaurant_id" integer NOT NULL,
  "name_en" varchar(160) NOT NULL,
  "name_kh" varchar(160) DEFAULT NULL,
  "category" varchar(50) DEFAULT 'local',
  "price_usd" decimal(8,2) DEFAULT NULL,
  "image_url" varchar(300) DEFAULT NULL,
  "description_en" text DEFAULT NULL,
  "is_active" smallint DEFAULT 1,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "reviews" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "place_id" integer NOT NULL,
  "rating" smallint NOT NULL,
  "comment" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "reviews_uq_rv_key" UNIQUE ("user_id", "place_id")
);

CREATE TABLE "transport_applications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "name" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "email" varchar(120) NOT NULL,
  "telegram" varchar(80) DEFAULT NULL,
  "home_address" text NOT NULL,
  "id_card_no" varchar(60) NOT NULL,
  "id_card_photo" varchar(400) DEFAULT NULL,
  "vehicle_type" varchar(20) NOT NULL DEFAULT 'taxi' CHECK ("vehicle_type" IN ('taxi','tuk_tuk','van','bus','other')),
  "vehicle_model" varchar(120) DEFAULT NULL,
  "vehicle_capacity" smallint DEFAULT 4,
  "license_plate" varchar(30) DEFAULT NULL,
  "driving_license" varchar(60) DEFAULT NULL,
  "vehicle_photo" varchar(400) DEFAULT NULL,
  "base_province" varchar(80) DEFAULT NULL,
  "price_per_day" decimal(8,2) DEFAULT NULL,
  "warranty_letter" varchar(400) DEFAULT NULL,
  "guarantor_name" varchar(120) DEFAULT NULL,
  "guarantor_phone" varchar(40) DEFAULT NULL,
  "guarantor_id" varchar(60) DEFAULT NULL,
  "guarantor_rel" varchar(80) DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "transport_bookings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "reference" varchar(20) NOT NULL,
  "partner_id" integer DEFAULT NULL,
  "tourist_name" varchar(120) NOT NULL,
  "passport_id_no" varchar(60) DEFAULT NULL,
  "email" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "vehicle_type" varchar(20) NOT NULL DEFAULT 'taxi' CHECK ("vehicle_type" IN ('taxi','tuk_tuk','van','bus','other')),
  "pickup_location" varchar(400) NOT NULL,
  "dropoff_location" varchar(400) NOT NULL,
  "trip_date" date NOT NULL,
  "trip_time" time NOT NULL,
  "num_passengers" smallint DEFAULT 1,
  "notes" text DEFAULT NULL,
  "total_usd" decimal(10,2) NOT NULL,
  "deposit_usd" decimal(10,2) NOT NULL,
  "balance_usd" decimal(10,2) NOT NULL,
  "payment_status" varchar(20) DEFAULT 'pending' CHECK ("payment_status" IN ('pending','pending_review','deposit_paid','fully_paid','refunded','expired')),
  "payment_due_at" timestamp DEFAULT NULL,
  "paid_at" timestamp DEFAULT NULL,
  "payment_reference" varchar(80) DEFAULT NULL,
  "payment_proof" varchar(255) DEFAULT NULL,
  "booking_status" varchar(20) DEFAULT 'pending' CHECK ("booking_status" IN ('pending','confirmed','in_progress','completed','cancelled')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "transport_bookings_reference_key" UNIQUE ("reference")
);

CREATE TABLE "transport_partners" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(120) NOT NULL,
  "phone" varchar(40) NOT NULL,
  "email" varchar(120) DEFAULT NULL,
  "telegram" varchar(80) DEFAULT NULL,
  "home_address" text DEFAULT NULL,
  "id_card_no" varchar(60) DEFAULT NULL,
  "id_card_photo" varchar(400) DEFAULT NULL,
  "vehicle_type" varchar(20) NOT NULL DEFAULT 'taxi' CHECK ("vehicle_type" IN ('taxi','tuk_tuk','van','bus','other')),
  "vehicle_model" varchar(120) DEFAULT NULL,
  "vehicle_capacity" smallint DEFAULT 4,
  "license_plate" varchar(30) DEFAULT NULL,
  "driving_license" varchar(60) DEFAULT NULL,
  "vehicle_photo" varchar(400) DEFAULT NULL,
  "base_province" varchar(80) DEFAULT NULL,
  "price_per_day" decimal(8,2) DEFAULT NULL,
  "warranty_letter" varchar(400) DEFAULT NULL,
  "guarantor_name" varchar(120) DEFAULT NULL,
  "guarantor_phone" varchar(40) DEFAULT NULL,
  "guarantor_id" varchar(60) DEFAULT NULL,
  "guarantor_rel" varchar(80) DEFAULT NULL,
  "status" varchar(20) DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected','suspended')),
  "is_active" smallint DEFAULT 0,
  "sort_order" integer DEFAULT 0,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "trip_places" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "trip_id" integer NOT NULL,
  "place_id" integer NOT NULL,
  "day_number" smallint DEFAULT 1,
  PRIMARY KEY ("id")
);

CREATE TABLE "trip_plans" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "title" varchar(200) DEFAULT 'My Cambodia Trip',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "user_points" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "points" decimal(12,2) NOT NULL,
  "amount_usd" decimal(10,2) DEFAULT NULL,
  "source_type" varchar(60) NOT NULL,
  "source_id" integer NOT NULL,
  "description" varchar(255) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_points_uq_user_points_source_key" UNIQUE ("source_type", "source_id")
);

CREATE TABLE "users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(150) NOT NULL,
  "email" varchar(200) NOT NULL,
  "phone" varchar(40) DEFAULT NULL,
  "bio" text DEFAULT NULL,
  "password_hash" varchar(255) NOT NULL,
  "avatar" varchar(10) DEFAULT '?',
  "profile_photo" varchar(255) DEFAULT NULL,
  "points_balance" decimal(12,2) NOT NULL DEFAULT 0.00,
  "preferred_lang" varchar(20) DEFAULT 'en' CHECK ("preferred_lang" IN ('en','kh')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "users_email_key" UNIQUE ("email")
);

CREATE TABLE "weather_months" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "province_id" integer NOT NULL,
  "month_num" smallint NOT NULL,
  "month_name" varchar(20) NOT NULL,
  "season" varchar(20) NOT NULL CHECK ("season" IN ('dry','wet')),
  "avg_temp_c" smallint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "weather_months_uq_wm_key" UNIQUE ("province_id", "month_num")
);


-- ===== Indexes =====
CREATE INDEX "bookmarks_place_id_idx" ON "bookmarks" ("place_id");
CREATE INDEX "donations_user_id_idx" ON "donations" ("user_id");
CREATE INDEX "guide_applications_idx_ga_user_id_idx" ON "guide_applications" ("user_id");
CREATE INDEX "guide_bookings_fk_gb_guide_idx" ON "guide_bookings" ("guide_id");
CREATE INDEX "guide_bookings_idx_gb_user_id_idx" ON "guide_bookings" ("user_id");
CREATE INDEX "guide_bookings_idx_gb_payment_due_idx" ON "guide_bookings" ("payment_due_at");
CREATE INDEX "hotel_restaurant_reservations_item_type_idx" ON "hotel_restaurant_reservations" ("item_type");
CREATE INDEX "hotel_restaurant_reservations_hotel_id_idx" ON "hotel_restaurant_reservations" ("hotel_id");
CREATE INDEX "hotel_restaurant_reservations_restaurant_id_idx" ON "hotel_restaurant_reservations" ("restaurant_id");
CREATE INDEX "hotel_restaurant_reservations_province_id_idx" ON "hotel_restaurant_reservations" ("province_id");
CREATE INDEX "hotel_restaurant_reservations_status_idx" ON "hotel_restaurant_reservations" ("status");
CREATE INDEX "hotel_restaurant_reservations_idx_hr_user_id_idx" ON "hotel_restaurant_reservations" ("user_id");
CREATE INDEX "hotel_restaurant_reservations_idx_hr_payment_status_idx" ON "hotel_restaurant_reservations" ("payment_status");
CREATE INDEX "hotel_restaurant_reservations_idx_hr_payment_due_idx" ON "hotel_restaurant_reservations" ("payment_due_at");
CREATE INDEX "hotels_province_id_idx" ON "hotels" ("province_id");
