COMMENT ON COLUMN "festivals"."place_id" IS 'Optional link to places table';
COMMENT ON COLUMN "festivals"."provinces" IS '[{"code":"PP","name":"Phnom Penh","color":"#CC1F27","primary":true}]';
COMMENT ON COLUMN "places"."main_product_en" IS 'Famous product or highlight (e.g. Durian, Bamboo Train, Bat Caves)';
COMMENT ON COLUMN "places"."main_product_kh" IS 'Khmer version of main product';
COMMENT ON COLUMN "places"."services_en" IS 'Available services (e.g. Food & Drink, Guide, Boat Rental)';

-- ===== updated_at auto-update (replaces MySQL ON UPDATE CURRENT_TIMESTAMP) =====
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "guide_applications_set_updated_at" BEFORE UPDATE ON "guide_applications" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "guide_bookings_set_updated_at" BEFORE UPDATE ON "guide_bookings" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "guides_set_updated_at" BEFORE UPDATE ON "guides" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "province_shops_set_updated_at" BEFORE UPDATE ON "province_shops" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "transport_applications_set_updated_at" BEFORE UPDATE ON "transport_applications" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "transport_bookings_set_updated_at" BEFORE UPDATE ON "transport_bookings" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER "transport_partners_set_updated_at" BEFORE UPDATE ON "transport_partners" FOR EACH ROW EXECUTE FUNCTION set_updated_at();

